INSERT INTO "WisdomModule" ("id","cycleId","title","subtitle","sortOrder","status","lifeQuestions","perspectives","tensionGuide","tensionGuideAudioUrl","discussionPrompts","summary","updatedAt") VALUES ($wib$wib-module-1$wib$, $wib$wib-cycle-1$wib$, $wib$第 1 課 什麼是智慧？$wib$, $wib$敬畏、失效與苦難中的尋求$wib$, 1, $wib$published$wib$, $wib$[{"id": "600868a1-1f96-4825-b94b-cfb842f31dc9", "text": "在你每星期生活，除了睡覺，飲食，個人護理清潔，家務（清潔和煮食），交通，工作糊口的時間使用外，列出一，兩種活動你會花時間去做", "type": "open", "options": [], "mediaUrl": "", "imageUrl": "", "imageAlt": ""}, {"id": "b0df0cd9-1a37-499e-b1d0-b5346e0ab2f0", "text": "你現在認為自己是否尋找「智慧」的人?", "type": "multi_choice", "options": ["是", "不是", "不知道"], "mediaUrl": "", "imageUrl": "", "imageAlt": ""}]$wib$::jsonb, $wib${"PROVERBS": {"book": "箴言", "theme": "人生一開始就在「選擇」中", "description": "【人生一開始就在「選擇」中（第 1 章）】\n「敬畏耶和華是知識的開端。」—— 箴言 1:7\n「我呼喚，你們不肯聽從；我伸手，無人理會。」—— 箴言 1:24\n「愚昧人背道，必殺己身；愚頑人安逸，必害己命。」—— 箴言 1:32\n\n● 重點：\n1. 智慧不是中立的資訊，而是一開始就要回應的呼召。\n2. 不選擇，其實也是一種選擇。\n\n【最後的邀請：兩條路、兩個宴席（第 9 章）】\n「智慧建造房屋，鑿成七根柱子。」—— 箴言 9:1\n「你們愚蒙人，要捨棄愚蒙，就得存活；並要走光明的道路。」—— 箴言 9:6\n「敬畏耶和華是智慧的開端。」—— 箴言 9:10\n\n● 重點：\n1. 人生最後不是「有沒有智慧」，而是：你進了哪一個宴席？", "imageUrl": "", "imageAlt": "", "audioUrl": ""}, "ECCLESIASTES": {"book": "傳道書", "theme": "智慧仍會失效", "description": "「多有智慧，就多有愁煩。」（傳 1:18）。傳道者誠實地指出：智慧不等於成功，正直不等於公平。當人看清制度與人性的限制，反而可能感到更痛苦。智慧並非替人生「保證結果」的魔法。", "imageUrl": "", "imageAlt": "", "audioUrl": ""}, "JOB": {"book": "約伯記", "theme": "智慧不能避免苦難", "description": "「他在智慧上有能力。」（伯 12:13）。約伯敬畏神且滿有智慧，卻仍在一夕之間失去一切。這反對了一種簡化的因果論：只要「做對的事」就不會「出意外」。真智慧是在極端痛苦中仍不虛假。", "imageUrl": "", "imageAlt": "", "audioUrl": ""}}$wib$::jsonb, $wib$【聖經中「智慧」】

● 箴言：智慧是「選擇正確人生方向」

核心經文
「敬畏耶和華是智慧的開端。」
—— 箴言 9:10

重點說明
• 箴言的智慧是實踐性的、方向性的
• 智慧不是抽象思想，而是每天在「路口」作出選擇
• 關鍵不在聰不聰明，而在你聽誰的聲音、走哪條路

● 傳道書：智慧是「誠實面對人生的有限與虛空」

核心經文
「我專心用智慧尋求、查究天下所做的一切事；乃知這也是捕風。」
—— 傳道書 1:13–14（節選）

重點說明
• 傳道書的智慧不是教你「如何成功」，而是教你不自欺
• 它揭露：人生不一定公平、努力不一定有回報
• 智慧在這裡是清醒，而不是樂觀

● 約伯記：智慧是「在無解的苦難中仍然不虛假」

核心經文
「敬畏主就是智慧；遠離惡便是聰明。」
—— 約伯記 28:28

重點說明
• 約伯記反對一種簡化邏輯：聰明／正直／敬虔 → 就不該受苦
• 在這裡，智慧不是解釋苦難，而是在苦難中仍然誠實地活著、不扮演假答案

⸻

【跨越時空的對話：西方文學的智慧視角】

1. 《理想國》— 柏拉圖：思考你是否真的在看見真實。
2. 《沉思錄》— 馬可・奧理略：如何在不可控的世界中保持內在秩序。
3. 《查拉圖斯特拉如是說》— 尼采：如何直面虛無並重新創造價值。
4. 《卡拉馬助夫兄弟》— 杜斯妥也夫斯基：自由、責任與信仰的重量。
5. 《老人與海》— 海明威：尊嚴來自於不放棄。

⸻

【跨越時空的對話：東方文學的智慧視角】

1. 《論語》— 孔子及其弟子：智慧是日常實踐中的做人之道與關係倫理。
2. 《莊子》— 莊周：不被成功定義，在相對性中尋求精神自由。
3. 《周易》（易經）：在變化中理解情勢演化與時機判斷。
4. 《史記》— 司馬遷：歷史是人性的全景，非勝者的獨白。
5. 《紅樓夢》— 曹雪芹：看透繁華幻滅，以清醒換取慈悲。

一條中國智慧的隱線

這五部作品共同指向一種不同於「征服世界」的智慧取向：
理解變化、安頓自身、在關係與無常中保持清明。

⸻

核心轉向：從「期待智慧給我答案」轉向「智慧讓我在任何處境中都選對宴席」。$wib$, $wib$https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1770305942142-yvodtx.mp3$wib$, $wib$["【選擇的代價】箴言提到「呼喚與拒絕」。在你的生活中，有沒有經歷「智慧的呼喚」是你一直在推延、不願聽從的？", "【宴席的辨識】\n\n箴言 9 章提到兩個宴席。\n\n「智慧的宴席」\n1-6 智慧建造房屋，鑿成七根柱子，宰殺牲畜，調好美酒，又擺設筵席，派遣女僕出去，自己在城中至高處呼喚：\n「誰是愚蒙的人，讓他轉到這裏來！」又對那無知的人說：「你們來，吃我的餅，喝我調的酒。你們要離棄愚蒙，就得存活，並要走明智的道路。」\n\n「愚蒙的宴席」\n9：13-18 愚昧的女子喧嚷，她是愚蒙，一無所知。她坐在自己家門口，在城中高處的座位上，呼喚過路的，向那些在路上直走的人說：「誰是愚蒙的人，讓他轉到這裏來！」又對那無知的人說：「偷來的水是甜的，暗藏的餅是美的。」人卻不知有陰魂在她那裏，她召喚的人是在陰間的深處。\n\n你認為現代社會中，哪一種「愚蒙的宴席」最容易讓人感到「有智慧」但這卻是「害命」的生活態度。", "【信仰的張力】如果智慧（你認定係要敬畏神），是不能一定保證你遠離苦難（傳道書/約伯記），你還會選擇走這條「敬畏」的路嗎？為什麼？  "]$wib$::jsonb, $wib$智慧不是用來掌控人生以求安穩，而是在萬變的世界中，每天都選擇走進「敬畏神」的宴席或行「敬畏神」的路。$wib$, CURRENT_TIMESTAMP);
INSERT INTO "WisdomModule" ("id","cycleId","title","subtitle","sortOrder","status","lifeQuestions","perspectives","tensionGuide","tensionGuideAudioUrl","discussionPrompts","summary","updatedAt") VALUES ($wib$wib-module-2$wib$, $wib$wib-cycle-1$wib$, $wib$第 2 課  因果報應是真的嗎？$wib$, $wib$當善惡與報償不再掛鉤$wib$, 2, $wib$published$wib$, $wib$[{"id": "2b1a407e-253e-4d08-9de9-2d5c8c5e09ca", "text": "在箴言 第8章 10-21 「智慧頌」\n\n10 你們當領受我（智慧）的訓誨，勝過領受銀子，寧得知識，強如得上選的金子。\n11「因為智慧比寶石更美，一切可喜愛的都不足與其比較。\n12 我－智慧以靈巧為居所，又尋得知識和智謀。\n13 敬畏耶和華就是恨惡邪惡；我恨惡驕傲、狂妄、惡道，和乖謬的口。\n14 我有策略和健全的知識，我聰明，又有能力。\n15 君王藉我治國，王子藉我定公平，\n16 王公貴族，所有公義的審判官，都藉我掌權。\n17 愛我的，我也愛他，懇切尋求我的，必尋見。\n18 財富和尊榮在我，恆久的財寶和繁榮也在我。\n19 我的果實勝過金子，強如純金，我的出產超乎上選的銀子。\n20 我在公義的道上走，在公平的路中行，\n21 使愛我(智慧)的承受財產，充滿他們的庫房。\n\n箴言第8章21節 好像說「好人有好報」，如果是，當你看到好人受苦時，日常見「好人沒有好報」，會否對你敬畏神的心有影響？\n\n", "type": "multi_choice", "options": ["有影響", "冇影響"], "mediaUrl": "", "imageUrl": "", "imageAlt": ""}, {"id": "5bc8dd2d-d783-4e26-b5cc-9332ec10c0c3", "text": "一個「好人沒有好報」的故事\n\n2025年12月，美國名導演（香港/台湾： 出名電影《義海雄風》或《軍官與魔鬼》 ）羅布·雷納和他太太米歇爾·雷納在家中遇害，疑兇是他患有精神病的親生兒子。\n\n羅布和米歇爾·雷納與一位曾被判死刑的德州男子建立起非凡的友誼。\n\n雷納夫婦與威廉斯之間的情誼，建立在羅布威廉斯作品中反覆出現的主題之上——愛、選擇的家庭、同情和救贖。雷納夫婦是好人，與一個在誤判為殺人犯的受害者，建立友誼，給與愛，但他們卻是另一個悲劇的受害者。\n\n有興趣點擊連結，了解故事，可用瀏覽器翻譯功能，以中文閱讀。", "type": "open", "options": [], "mediaUrl": " https://www.nbcnews.com/news/us-news/rob-reiner-michele-texas-nanon-williams-sentenced-death-rcna252305", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/life-question-images/1768240673684-u3zuow.jpeg", "imageAlt": "電影《義海雄風》海報"}, {"id": "359e5522-7983-4690-b16c-c55d796d9824", "text": "生活中是否有觀察過「壞人飛黃騰達」的現況，讓你感到憤怒或有其他感覺嗎？嘗試以祈禱的心寫下向神抒發你的感受", "type": "open", "options": [], "mediaUrl": "", "imageUrl": "", "imageAlt": ""}]$wib$::jsonb, $wib${"PROVERBS": {"book": "箴言", "theme": "善惡有別", "description": "一、善惡是「兩條路」，不是一條路的兩端\n\n「義人的路好像黎明的光，越照越明；\n惡人的道好像幽暗，自己不知因何跌倒。」箴言 4:18–19\n\n「不可行惡人的路；不要走壞人的道。」箴言 4:14\n\n二、善惡可以分辨，不是模糊不清\n\n「愚蒙人是話都信；通達人步步謹慎。」箴言 14:15\n\n「惡人不明白公平；惟有尋求耶和華的，無不明白。」箴言 28:5\n\n三、善惡結局不同，不是「最後都一樣」\n\n「惡人雖然連手，必不免受罰；義人的後裔必得拯救。」箴言 11:21\n\n「義人所結的果子就是生命樹。」箴言 11:30\n", "imageUrl": "", "imageAlt": "", "audioUrl": ""}, "ECCLESIASTES": {"book": "傳道書", "theme": "義人受苦", "description": "一、傳道書直接承認：壞人真的會興旺\n\n「有一件虛空的事發生在世上：\n義人所遭遇的，反照惡人所行的；\n惡人所遭遇的，反照義人所行的。」傳道書 8:14\n\n「我見日光之下所行的一切事，有義人行義，反得短命；有惡人行惡，倒享長壽。」傳道書 7:15\n\n二、為何壞人會興旺？世界不是即時審判系統\n\n「因為斷定罪名不立刻施刑，所以世人滿心作惡。」傳道書 8:11\n\n「凡事都有定期；天下萬務都有定時。」傳道書 3:1\n\n三、面對壞人興旺，智慧不是犬儒，而是節制與敬畏\n\n「不要行義過分，也不要過於自逞智慧，\n何必自取敗亡呢？」傳道書 7:16\n\n「我知道敬畏神的，就是在他面前敬畏的人，終久必得福樂。」傳道書 8:12（節選）", "imageUrl": "", "imageAlt": "", "audioUrl": ""}, "JOB": {"book": "約伯記", "theme": "義人崩潰", "description": "第一層崩潰：沉默瓦解（身體與存在層面）\n\n「約伯便坐在爐灰中，拿瓦片刮身。」約伯記 2:8 \n\n「他們就同他七天七夜坐在地上，一個人也不向他說話，因為他極其痛苦。」約伯記 2:13\n\n第二層崩潰：語言失控（心理與情感層面）\n\n「約伯開口咒詛自己的生日。」約伯記 3:1\n\n「為何不出母胎而死？為何不出母腹就斷氣？」約伯記 3:11\n\n第三層崩潰：信仰張力（向神控訴而非離棄）\n\n「我向神呼求，你卻不應允我；我站著，你只顧看我。」約伯記 30:20\n\n「他雖殺我，我仍要仰望他；\n然而我要在他面前辯明我所行的。」約伯記 13:15\n", "imageUrl": "", "imageAlt": "", "audioUrl": ""}}$wib$::jsonb, $wib$【一套隱形神學】

・生活在香港資本主義市場制度下，「好人沒有好報」與「壞人飛黃騰達」是常態。
・理解與「合理化」解釋這個現象。
 
一、資本主義獎勵的是「結果」，不是「品格」

・核心邏輯市場制度的基本判準是：是否有效率地創造可交換的價值（利潤、市佔率、回報）

・市場不是針對：是否正直？是否善良？是否對社會長遠有益？好人若效率低、資源少、話語權弱 → 不被獎勵。壞人若敢冒險、踩灰線、剝削他人 → 短期被獎勵

二、「壞人飛黃騰達」往往是因為他們更願意轉嫁風險

類型        好人        壞人 
風險態度    避免傷害他人  願意讓他人承擔
法律邊界    保守         灰色操作
道德成本    自己內化      外部化給別人

三、「好人沒有好報」常因為好人承擔了「不可定價的成本」

這些成本包括：良心壓力，對他人的責任感，不願說謊、不願傷人，拒絕不公平競爭手段。問題是這些東西在市場中沒有價格標籤，可以很高也可一文不值。

香港人往往認同，成功 → 對的人； 失敗 → 錯的人； 成功的壞人 → 聰明、現實； 失敗的好人 → 天真、幼稚。
其實不是單純的經濟觀察，而是一套神學或價值觀。

箴言教你：不要把「贏」當成「對」。「有一條路，人以為正（「贏」在起跑線），至終成為死亡之路。」箴言 14:12
傳道書教你：在不公平的世界中，不要走向極端。「不要行義過分，也不要過於自逞智慧；何必自取敗亡呢？」傳道書 7:16
約伯記教你：當這一切把你壓垮時，你仍未被否定。「他雖殺我，我仍要仰望他；然而我要在他面前辯明我所行的。」約伯記 13:15

聖經智慧文學教導
	•	✅ 成功者被視為「對的人」→ 箴言說：看路，不看獎杯
	•	✅ 失敗者被視為「不夠努力」→ 傳道書說：這是虛空，不是真理
	•	✅ 壞人成功被美化為聰明 → 傳道書說：這只是延遲的問題，不是證明
	•	✅ 好人失敗被嘲諷為天真 → 約伯記說：這種嘲諷本身就是錯的神學
$wib$, $wib$https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1770306191814-amqixq.mp3$wib$, $wib$["市場告訴你誰贏了，但聖經智慧文學問你，在這個世界裡，你還要不要成為一個「被市場決定」價值的人？敬畏神，在神的安排下，認識自己。與組員分享你對自己價值的看法。\n", "當「因果」失效時，有什麼支撐你繼續選擇「敬畏神」？與組員探索教會群體如何活出「敬畏神」生活。 "]$wib$::jsonb, $wib$信仰不是投資，而是即使在混亂中，仍選擇守住信心。$wib$, CURRENT_TIMESTAMP);
INSERT INTO "WisdomModule" ("id","cycleId","title","subtitle","sortOrder","status","lifeQuestions","perspectives","tensionGuide","tensionGuideAudioUrl","discussionPrompts","summary","updatedAt") VALUES ($wib$wib-module-3$wib$, $wib$wib-cycle-1$wib$, $wib$第 3 課  認識有智慧的自由$wib$, $wib$要自由能否敬畏神？敬畏神能否享受自由？$wib$, 3, $wib$published$wib$, $wib$[{"id": "3b54c364-dad6-41c3-8771-8b24838a1eb9", "text": "串流電視 Netflix 名劇《怪奇物語》，播放10年，由這劇集的演員的變化，可見時間匆匆，轉眼就10年。分享你對時間感覺。", "type": "open", "options": [], "mediaUrl": "https://youtube.com/shorts/zsK0k5Rui_w?si=Vd8fHqInr0wpRnCz", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/life-question-images/1768220163900-x8w4by.jpeg", "imageAlt": "《怪奇物語》Stranger Things 海報"}, {"id": "c33daf2f-ed4a-4fb4-ac54-45143a9f6084", "text": "人生匆匆，轉眼就幾十年，如果有機會不好好自由地享受人生，好像有點浪費。箴言說尋求「智慧」，「敬畏神」 你覺得會不會阻撓自由地享受人生？以誠實的心向神表明你的感受。若覺得可以和弟兄姊妹一起分享，寫下來，會以「不記名」的發放。", "type": "open", "options": [], "mediaUrl": "", "imageUrl": "", "imageAlt": ""}, {"id": "9602bbd0-c0d1-446c-8e93-633b62dbb12a", "text": "美國總統唐納德·川普在2026年1月初，發動了一場閃電戰，推翻了委內瑞拉領導人尼古拉斯·馬杜羅，並威脅了許多其他國家以及要佔領格陵蘭島領土。2026年1月8日，他在接受《紐約時報》採訪時發表了一個很多人或多或少行事標準的言論。\n\n「是的，有一件事。那就是我自己的道德準則。我自己的思想。只有這些才能阻止我，」川普在被問及他的全球權力是否有任何限制時告訴該報。「我不需要國際法（法律或人為限制），」他補充道。 「我不想傷害任何人。」\n\n一個在「基督裏」的人，不就應該像川普以「自己『屬靈』經驗」，在神裏的得著，去作「道德」或生活決擇。你覺得⋯⋯", "type": "multi_choice", "options": ["是", "不是", "不知道"], "mediaUrl": "https://www.google.com/search?q=trump+say+there+is+no+international+law&oq=trump+say+there+is+no+international+law&gs_lcrp=EgZjaHJvbWUyBggAEEUYOTIHCAEQIRiPAjIHCAIQIRiPAtIBCTIyMTAwajBqN6gCCLACAfEFYLAyfWPdrLo&sourceid=chrome&ie=UTF-8#fpstate=ive&vld=cid:3230abcf,vid:BybwEMSUBng,st:0", "imageUrl": "", "imageAlt": ""}]$wib$::jsonb, $wib${"PROVERBS": {"book": "約伯記 8:1-3， 13-21", "theme": "約伯請求神不要理他", "description": "「人在世上豈無勞役呢？他的日子不像雇工的日子嗎？像奴僕切慕陰涼，像雇工等待工錢，\n我也照樣度過虛空的歲月，愁煩的夜晚指定給我。我若說：『我的床必安慰我，我的榻必分擔我的苦情』，」\n\n「你（神）就用夢驚擾我，用異象恐嚇我。甚至我寧可窒息死亡，勝似留我這副骨頭。我厭棄生命，不願永遠活著。你任憑我吧，因我的日子都是虛空。人算甚麼，你竟看他為大，將他放在心上，每早晨鑒察他，每時刻考驗他？你（神）到何時才轉眼不看我，任憑我咽下唾沫呢？鑒察人的主啊，我若有罪，於你何妨？為何以我當你的箭靶，使我成為你的重擔呢？為何不赦免我的過犯，除掉我的罪孽呢？我現今要躺臥在塵土中；你要切切尋找我，我卻不在了。」", "imageUrl": "", "imageAlt": "", "audioUrl": ""}, "ECCLESIASTES": {"book": "箴言 3:5-8， 21-26", "theme": "敬畏神所帶來的這種被神照顧的自由", "description": "「你要專心仰賴耶和華，不可倚靠自己的聰明；在你一切所行的事上都要認定他，他必指引你的路。不要自以為有智慧；要敬畏耶和華，遠離惡事。這便醫治你的肚腹，滋潤你的百骨。」\n\n「我兒，要謹守真智慧和謀略，不可使他離開你的眼目；這樣，他必作你的生命，頸項的美飾。你行走，腳步必不至狹窄；你奔跑，也不至跌倒。你躺下，必不懼怕；你躺臥，睡得香甜。忽然來的驚恐，不要害怕；惡人遭毀滅，也不要恐懼。因為耶和華是你所倚靠的，他必保守你的腳不陷入網羅。」\n\n", "imageUrl": "", "imageAlt": "", "audioUrl": ""}, "JOB": {"book": "傳道書3: 1， 11-14", "theme": "人生不能掌控自己。", "description": "「凡事都有定期，天下萬務都有定時。」\n\n「神造萬物，各按其時成為美好，又將永生安置在世人心裡；然而神從始至終的作為，人不能參透。我知道世人，莫強如終身喜樂行善；並且人人吃喝，在他一切勞碌中享福，這也是神的恩賜。我知道神一切所做的，都必永存；無所增添，無所減少。神這樣行，是要人在他面前存敬畏的心。」", "imageUrl": "", "imageAlt": "", "audioUrl": ""}}$wib$::jsonb, $wib$一、川普的自由主義分析

約束他的道德標準，不是外在法則（政府制度，組織規範），而是內在的道德準則與思想。他說不需要外在法律；他不想傷害任何人。

這句話包含三個核心前設： 
	1.	道德的最終來源在「自我內部」
	2.	外在約束（國際法、制度）不是必要的
	3.	善惡判準＝我的意圖

【智慧書教導】
① 約伯記 8 章：描述人有不要神介入的時候

核心經文提醒：被神看顧，本應是恩典，但在約伯或你的處境中，卻變成壓力與審問。揭示了敬畏中的一個深層矛盾，當神的臨在不再帶來安慰，敬畏就不再是安全感，而成為重負，不自由感覺。
 
張力
。川普的話隱含一個假設：「只要我是理性且善意的，自我內心道德標準本身不是問題。」可自由行事，會時常出現想不要神介入時候。 

。約伯記：敬畏神和不自由的感覺。敬畏神，是不逃離神，有時有極度不自由的感覺，在這種張力中，沒有「被神」否定，神仍在。
  
  

②箴言 3 章：敬畏神所帶來的這種被神照顧的「自由」 

核心經文提醒： 不倚靠自己的聰明，不自以為有智慧，敬畏神的人的路被引導，神為外在約束力。但不受恐懼和憂慮所限制。
 
張力
。川普說：「只有我的道德與思想能限制我。」。

。箴言：「自以為智慧」本身，就是失去敬畏，恐懼和憂慮就限制他。



③傳道書 3 章：人生不能掌控自己。不要追逐自以為是的自由。
 
核心經文提醒：人不能掌控時機，人不能理解全局。神如此行，是要人存敬畏的心。

傳道書的自由不是「我說了算」，而是承認有些事情不是我說了算，因我有限，不應該扮演上帝。

張力
。川普的話，實際上是在宣告，「是否傷害他人，由我自己判定。」

。傳道書：人正因為看不見全貌，不知道是否傷害他人，不能由自己判定，需要敬畏神，衪指引。


$wib$, $wib$https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1770306420673-mkoi4x.mp3$wib$, $wib$["1. \t箴言論述的，不靠自己聰明判斷，包括自己。而川普的道德標準，是用他自己判斷自己，你覺得那一種比較自由？分享你見解。 ", "2. 有人說自由主義的人嚮往的無外界約束道德標準，聖經智慧書真正警惕是沒有外在界線的道德標準約束。你同不同意？分享你意見。\n"]$wib$::jsonb, $wib$在舊約智慧書裡，敬畏神不是讓人失去自由，而是讓人停止追求一種本來就不屬於人的自由。

小心你自己執著不受外界約束的行為，自我判斷的自由，這不是智慧。

馬太福音 11: 18-19 『約翰來了，既不吃也不喝，人們就說他是被鬼附的；人子來了，也吃也喝，他們又說這人貪食好酒，是稅吏和罪人的朋友。而（人的）智慧（若是敬畏神）是由它的果子來證實的（不是它所做）。 』  $wib$, CURRENT_TIMESTAMP);
INSERT INTO "WisdomModule" ("id","cycleId","title","subtitle","sortOrder","status","lifeQuestions","perspectives","tensionGuide","tensionGuideAudioUrl","discussionPrompts","summary","updatedAt") VALUES ($wib$wib-module-4$wib$, $wib$wib-cycle-1$wib$, $wib$第 4 課 一命，二運，三風水，四積陰德，五讀書（追求智識）⋯⋯你信影響著你的際遇？$wib$, $wib$活在神的創造所擺設的界限中$wib$, 4, $wib$published$wib$, $wib$[{"id": "61bc6da6-9757-4611-b31f-474b9ba893fb", "text": "你覺得「智識」是生活在現代社會是一種生存優勢，還是一種消費活動？", "type": "multi_choice", "options": ["消費活動", "生存優勢", "不知道"], "mediaUrl": "https://youtu.be/LkPWwXYq5bM?si=tvvUL9N9a6jTU6jM", "imageUrl": "", "imageAlt": ""}, {"id": "9f58ff14-a23b-4ed4-931e-1d158c7dae05", "text": "我們大部分都是成長上世紀70， 80， 90年代，努力，尋求知識是我們生活態度，你對現在有年輕人嚮往「躺平」生活態度有冇感覺？", "type": "multi_choice", "options": ["沒有感覺", "不知道", "有感覺"], "mediaUrl": "https://youtu.be/1EgzfUp7E0w?si=AuVvU5gbNsQZP-8-", "imageUrl": "", "imageAlt": ""}]$wib$::jsonb, $wib${"PROVERBS": {"book": "箴言 8:22-31", "theme": "智慧頌", "description": "在耶和華創造的開始，在太初創造一切以先，就有了我（智慧）。在亙古、在太初，在未有大地之前，我已經被立；沒有深淵，沒有大水的泉源以先，我已經出生。大山未曾奠定，小山未有以先，我已經出生。那時，耶和華還沒有造大地和田野，也沒有造地上的泥土。他（耶和華）立定諸天的時候，我（智慧）在那裡；他在淵面上界劃地平線的時候，我在那裡；他上使穹蒼堅固，下使深淵的水泉穩定；他為海洋定出界限，海水不能越過他的命令，他又劃定大地的根基；那時，我在他身邊作工匠，每天都充滿喜樂，時常在他面前歡笑，在他的大地上歡笑，和世人一同喜樂。", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/perspective-images/1768835737083-rr2d02.jpeg", "imageAlt": "", "audioUrl": ""}, "ECCLESIASTES": {"book": "約伯記 28:12-28", "theme": "歌頌智慧", "description": "然而，智慧何處可尋？聰明之地在哪裏？智慧的價值無人能知，活人之地也無處可尋。深淵說：『不在我裏面。』滄海說：『不在我這裏。』智慧不可用黃金換取，也不能用白銀秤她的價值。俄斐的金子和貴重的紅瑪瑙，以及藍寶石，不足與她比擬；黃金和玻璃不足與她比較；純金的器皿不足兌換她（智慧）。珊瑚、水晶都不值得提；智慧的價值勝過寶石。古實的紅璧璽不足與她比較；純金也不足與她比擬。「智慧從何處來呢？聰明之地在哪裏？她隱藏，遠離眾生的眼目，她掩蔽，遠離空中的飛鳥。毀滅和死亡說：『我們風聞其名。』「上帝明白智慧的道路，知道智慧的所在。因為他鑒察直到地極，遍觀普天之下，要為風定輕重，又度量諸水，為雨定律例，為雷電定道路。那時他看見智慧，就談論她，堅定她，並且查究她。他對人說：『看哪，敬畏主就是智慧；遠離惡事就是聰明。』」", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/perspective-images/1768835743776-yof42a.jpeg", "imageAlt": "", "audioUrl": ""}, "JOB": {"book": "傳道書 7:23–25， 8:16–17 ", "theme": "追求智慧的挫敗，無法參透神的作為", "description": "我曾用智慧試驗這一切事，我說（以為得到）：「要得智慧。」智慧卻離我遠。 萬事之理遙不可及，太深奧，誰能測透呢？ 我轉念，一心要知道，要考察，要尋求智慧和萬事的來由，⋯⋯。\n\n我專心想要明白智慧，要觀看世上所發生的事。有人晝夜不得闔眼睡覺。 我觀看上帝一切的作為，知道人不能探求日光之下所發生的事；任憑他費多少力探索，都找不出來，智慧人雖說他明白，仍不能找出來。", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/perspective-images/1768835750012-iduj7f.jpeg", "imageAlt": "", "audioUrl": ""}}$wib$::jsonb, $wib$智慧文學中，有三個信息告訴讀者：

。他們身處的宇宙，是一個奇妙的受造界，它的運作，秩序和非秩序（包括物質世界和非物質世界，和其之間關係），有智慧存在。
 
。智慧書都鼓勵「敬畏神」的人，辨識神創造世界運作的意義，但不容易找到，這好好東西是智慧。
 
。觀察神作為，明白智慧，人在其中建立和神關係。（不是人建立和神關係，就得到智慧） 
 
【中國民間命運觀：「一命，二運，三風水，四積陰德，五讀書」】可能是中國人經時日累積觀察。

不受掌握：命和運。 
可改變：風水，陰德，讀書。 

放回神創造的界限之內。

一命：命是神的創造
	•	約伯記 14:5　既然人的日子限定，他的月數在於你，你劃定他的「界限」，他不能越過；你會怎樣理解神創造給你「界限 」 

二運：時候和機會掌控在神 
	•	傳道書 9:11　我轉而回顧日光之下，快跑的未必能贏，強壯的未必戰勝，智慧的未必得糧食，聰明的未必得財富，有學問的未必得人喜悅，全在乎各人遇上的時候和機會。 你會怎樣明白「機會」是神創造
 
三風水：環境與處境
	•	箴言 3:5–6　你要專心仰賴耶和華，不可倚靠自己的聰明，在你一切所行的路上都要認定他，他必使你的道路平直。處境中，你會怎樣處理「認定」神，而不是羅盤方位

四積陰德：暗中的善行
	•	傳道書 12:14　'因為人所做的事，連一切隱藏的事，無論是善是惡，上帝都必審問。有限生命，你會怎樣預備「終極」時面對神。
 
五讀書：學問與智慧
	•	箴言 1:7　敬畏耶和華是知識的開端。在知識泛濫，你會怎樣處理每天遞送你面前的「知識」
 

$wib$, $wib$https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1770306643922-4i3khg.mp3$wib$, $wib$["分享一個個人經歷令你思考或理解神創造給你「界限」 ", "有弟兄分享神創造的「創造神學」，是可再創造的。而我們因基督被救贖，已是一種被再創造，你的「命」已經變了。分享你的意見", "分享一個經歷令你思考或明白「機會」是神創造", "明白有限生命，分享一件事你覺得是準備「終極」面對神。\n  "]$wib$::jsonb, $wib$智慧書找到有關「命、運、處境、善行、學問」教導，都真實影響人生，但都不是獨立運作的命理系統，是在神創造與主權運作界限和範圍中體驗。 $wib$, CURRENT_TIMESTAMP);
INSERT INTO "WisdomModule" ("id","cycleId","title","subtitle","sortOrder","status","lifeQuestions","perspectives","tensionGuide","tensionGuideAudioUrl","discussionPrompts","summary","updatedAt") VALUES ($wib$wib-module-5$wib$, $wib$wib-cycle-1$wib$, $wib$第 5 課 讓智慧觸摸你$wib$, $wib$智慧是要理解？是被共嗚？還是其他⋯⋯$wib$, 5, $wib$published$wib$, $wib$[{"id": "47634c9d-327d-4b27-9cf0-041436d37c2e", "text": "現今可以在YouTube 裏找到很多視頻，可能幫助你進入一個景界。你覺得原因是 ⋯⋯", "type": "open", "options": [], "mediaUrl": "https://youtu.be/6qvu82h7bWQ?si=uz5zsafaoxAvsAVc", "imageUrl": "", "imageAlt": ""}, {"id": "13e4eb72-9f23-4b1f-8749-710839d7a8ec", "text": "大家先一起聽這五卷書：箴言 第三章至第七章。父親對兒子勸導，今天你如有受作者心境感動，我為你感謝神，你能在回憶中與經文產生共鳴。很多人與父母之間每次只有在二、三十字內的心靈對話。能以箴言 第三章至第七章的長篇對話，並不容易。分享你與父親或母親的心靈對話。", "type": "multi_choice", "options": ["有", "冇", "其他"], "mediaUrl": "https://www.bible.com/audio-bible/139/PRO.3.RCUV", "imageUrl": "", "imageAlt": ""}]$wib$::jsonb, $wib${"PROVERBS": {"book": "箴言 3-7 章  以經文內容投影一個父女對話", "theme": "《城那邊的電話》", "description": "第一通電話，很輕。她說：「爸，我離開香港了。這裡空氣不一樣，沒有人問你站在哪一邊。」她笑了一下，又補一句：「好像終於可以呼吸。」父親答：「能呼吸是恩典。只是別忘了，心也需要空氣，不只是肺。」\n\n第二通電話，語速變快。\n她說：「多倫多很公平，工作只看能力。感情也是，大家說不用承諾，沒誰欠誰。」她停住，像在衡量自己是否說得太快：「這樣比較輕鬆，不用再失望。」父親說：「輕不一定是自由。有些重量，是為了讓人站得住。」\n\n第三通電話，是深夜。\n她壓低聲音：「爸，我不想再被任何制度、任何價值壓著。香港教我相信，結果卻是失去。」她呼了一口氣：「他們說界線是恐懼，忠誠是舊時代的語言。」父親沉默良久：「不是所有新聲音都帶你往前。有些只是把你帶離自己自小走的路。」\n\n第四通電話，情緒終於撞上來。\n她說：「那守呢？堅持呢？有什麼用？我不想再當那個認真的人。」父親的聲音緊了一下，又放柔：「正因為你看過崩塌，才知道什麼不是幻影。願意尋找智慧的人不是不跌倒，是不把心賣掉。」\n\n第五通電話，很慢。\n她說：「我好像一直在逃。逃離香港，也逃離親密。可是不管多自由，我都很不安。」父親答：「心若沒有安放的地方，世界再大也像流浪。敬畏神不保證安全，但她保守你。」\n\n最後一通電話，在清晨。\n她說：「爸，我想生活，重新學怎樣去愛，被愛。」\n父親說：「把心交給以前認識的神，不是回到過去，是選擇生命。路也許窄，但不虛空。」\n\n電話掛斷。\n城市醒來。\n她坐著，第一次沒有急著離開心靈聲音。\n", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1770305408185-a56uyk.mp3"}, "ECCLESIASTES": {"book": "傳道書 第三章 1-8", "theme": "萬事都有時", "description": "凡事都有定期，天下每一事務都有定時。生有時，死有時；栽種有時，拔出有時；殺戮有時，醫治有時；拆毀有時，建造有時；哭有時，笑有時；哀慟有時，跳舞有時；丟石頭有時，撿石頭有時；懷抱有時，不抱有時；尋找有時，失落有時；保存有時，拋棄有時；撕裂有時，縫補有時；沉默有時，說話有時；喜愛有時，恨惡有時；戰爭有時，和平有時。", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/perspective-images/1769403840770-332xzc.jpeg", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1770305286792-k2ajmv.mp3"}, "JOB": {"book": "約伯記 23章8-12", "theme": "衪究竟在不在？", "description": "「看哪，我往前走，他不在那裏；往後退，也沒有察覺他。他在左邊行事，我卻看不見他；\n他轉向右邊，我也見不到他。然而他知道我所走的路；他試煉我，我就如純金。我的腳緊跟他的步伐；我謹守他的道，並不偏離。他嘴唇的命令，我未曾背棄；」", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/perspective-images/1769403848458-mda8t8.jpeg", "imageAlt": "", "audioUrl": ""}}$wib$::jsonb, $wib$【第一個故事對應《箴言》3–7 章的結構分析】


一、第一通電話 ▶ 對應：箴言 3:1–12

主題：信靠與生命的起點

女兒：離開香港，終於可以呼吸
父親：心也需要空氣

箴言 3 章不是先談對錯，而是談「方向」：
	•	不倚靠自己
	•	在一切路上認定神
	•	得生命與平安

對應說明
	•	女兒追求的是「解放」
	•	父親關心的是「生命來源」

👉 這正是箴言 3 章的父親語氣：不是阻止你走，而是提醒你靠誰走。



二、第二通電話 ▶ 對應：箴言 4 章

主題：守心與人生道路

女兒：不用承諾，比較輕鬆
父親：有些重量，讓人站得住

箴言 4 章是整段智慧文學的核心：

「你要保守你心，勝過保守一切」

對應說明
	•	女兒覺得「輕」就是自由
	•	父親指出：失去重量，就失去方向

👉 這把「守心」從道德命令，轉為生存智慧。



三、第三通電話 ▶ 對應：箴言 5 章

主題：被引走的危險

女兒：不想再被制度壓著
父親：不是所有新聲音都帶你往前 

箴言 5 章警告的不是「性」本身，而是偏離生命軌道。

對應說明
	•	女兒渴望擺脫控制
	•	父親分辨「解放」與「引誘」

👉 這正是箴言的智慧：不是禁止慾望，而是指出結局。



四、第四通電話 ▶ 對應：箴言 6:20–35

主題：不要輕看失去心的代價

女兒：守有什麼用？
父親：不要把心賣掉

箴言 6 章談到：
	•	一時的衝動
	•	長遠無法挽回的失落

對應說明
	•	女兒已經在懷疑「認真是否值得」
	•	父親不是威嚇，而是心痛

👉 這完全符合箴言父親的角色：不是法官，是守望者。

⸻

五、第五通與最後一通電話▶ 對應：箴言 7 章

主題：兩種聲音，兩條路

女兒：我一直在逃，卻不安
父親：選擇生命，不是回到過去

箴言 7 章讓兩個聲音並行：
	•	誘惑的聲音（甜、即時、不用想）
	•	智慧的聲音（安靜、反覆、等你）

對應說明
	•	女兒終於停下來
	•	父親沒有催促，只留下方向

👉 結局不是「她做對了」，而是她開始聽神的智慧呼喚。
$wib$, $wib$https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1770305702996-8qel91.mp3$wib$, $wib$["1. 為什麼這比直接讀經文，有些人更容易「明白」箴言3-7章「智慧」，文學（可能是神另一樣希望我們感受到）裏描繪的「父親的急切」，像神對以色列人一樣。  ", "2. 「箴言」3-7章 父親對兒子對話，最著急的不是什麼是「正確」，而是「生命」。你對你兒女著急什麼？分享你的反思", "3.「傳道書」3:1-8，給我們的提醒，萬事有時。當我們心痛時，想起這段經文，有沒有感受到神給的安慰，再想「約伯記 」23: 8-12，你感受到神對你關心的人，他們仍然在神的照顧著嗎？令你的禱告熱心更有動力嗎？", ""]$wib$::jsonb, $wib$這篇故事不是把《箴言》現代化，而是讓我們重新聽見《箴言》3-7章，原本就是一位父親，在一個會吞人的世界裡，呼叫孩子選擇生命。$wib$, CURRENT_TIMESTAMP);
INSERT INTO "WisdomModule" ("id","cycleId","title","subtitle","sortOrder","status","lifeQuestions","perspectives","tensionGuide","tensionGuideAudioUrl","discussionPrompts","summary","updatedAt") VALUES ($wib$wib-module-6$wib$, $wib$wib-cycle-1$wib$, $wib$第 6 課  神裡的智慧$wib$, $wib$你為什麼要明白神裡的智慧 $wib$, 6, $wib$published$wib$, $wib$[{"id": "dd2a9cca-1884-4624-8aa0-c8e856f1ee68", "text": "【認識自己】：用現代人工智能來對比人腦，或許能讓你對人腦（智慧的我）有更深入的了解。", "type": "open", "options": [], "mediaUrl": "https://brain-potential.vercel.app", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/life-question-images/1770303828342-cpc15g.png", "imageAlt": ""}, {"id": "1d3a2573-08c9-4dfa-81a8-894c51d83e97", "text": "【認識神對我們要求】上學期有些同學參加了《申命記》主日學。《申命記》6:5 說：「你要盡心、盡性（soul or being）、盡力（strength or might or resources）愛耶和華——你的神。」這節經文向我們這些信徒提出了一個問題：我們應當如何看待自己的信仰？", "type": "open", "options": [], "mediaUrl": "", "imageUrl": "", "imageAlt": ""}, {"id": "d6934eea-6c31-4429-8a2b-022aea263ac9", "text": "【認識我對神的期望】在你的信仰旅程中，你更渴望的是一種「問題的解釋」、一位「生活的伴侶」，還是去尋找並完成「召命」？", "type": "multi_choice", "options": ["問題的解釋", "生活的伴侶", "召命人生", "不知道"], "mediaUrl": "", "imageUrl": "", "imageAlt": ""}]$wib$::jsonb, $wib${"PROVERBS": {"book": "列王紀上 3:3-15 ，4:29-32（箴言 第10-22章）", "theme": "所羅王的召命 - 智慧箴言管治。但他卻是⋯⋯。", "description": "所羅門 愛耶和華，遵行他父親 大衛 的律例，只是還在丘壇獻祭燒香。 \n\n所羅門 王到 基遍 ，在那裏獻祭，因為 基遍 有極大的丘壇。 所羅門 在那壇上獻了一千祭牲為燔祭。 在 基遍 ，耶和華夜間在夢中向 所羅門 顯現；上帝說：「你願我賜你甚麼，你可以求。」 所羅門 說：「你曾向你僕人我父親 大衛 大施慈愛，因為他用忠信、公義、正直的心行在你面前。你又為他存留大慈愛，賜他一個兒子坐在他的王位上，正如今日一樣。 現在，耶和華－我的上帝啊，你使僕人接續我父親 大衛 作王；但我是幼小的孩子，不知道應當怎樣出入。 僕人住在你揀選的百姓中，這百姓之多，多得不可點，不可算。 所以求你賜僕人善於了解的心，可以判斷你的百姓，辨別是非。不然，誰能判斷你這麼多的百姓呢？」 所羅門 因為求這事，就蒙主喜悅。 \n\n上帝對他說：「你既然求這事，不為自己求壽、求富，也不求滅絕你仇敵的性命，只求能明辨，可以聽訟， 看哪，我會照你的話去做，看哪，我會賜你智慧和明辨的心，在你以前沒有像你的，在你以後也沒有興起像你的。 你沒有求的，我也賜給你，就是富足、尊榮，使你在世一切的日子，列王中沒有一個能比你的。 你若遵行我的道，謹守我的律例、誡命，正如你父親 大衛 所行的，我必使你長壽。」 \n\n所羅門 醒了，看哪，是個夢。他就來到 耶路撒冷 ，站在耶和華的約櫃前，獻燔祭和平安祭，又為眾臣僕擺設宴席。 \n\n⋯⋯\n\n上帝賜給 所羅門 極大的智慧和聰明，以及寬闊的心，如同海邊的沙。 所羅門 的智慧超過所有東方人的智慧，和 埃及 人一切的智慧。 他的智慧勝過萬人，勝過 以斯拉 人 以探 ，以及 瑪曷 的兒子 希幔 、 甲各 、 達大 。他的名聲傳遍四圍的列國。 他作箴言三千句，詩歌一千零五首。 \n\n", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/perspective-images/1770303535422-udj7yb.jpeg", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1770304418389-f00sxz.mp3"}, "ECCLESIASTES": {"book": "傳道書 8:1-9,16-17", "theme": "傳道者對「尋求解釋」的回應⋯⋯。", "description": "誰如 智慧人呢？ 誰知道事情的解釋呢？ 人的智慧使他的臉發光， 改變他臉上的暴戾之氣 。 我勸你 因上帝誓言的緣故，當遵守王的命令。 不要急躁離開王的面前，不要固執行惡，因為他凡事都隨自己心意而行。 王的話本有權力，誰能對他說：「你在做甚麼？」 凡遵守命令的，必不經歷禍患；智慧人的心知道適當的時機和必經的過程。 各樣事務都有時機和過程，但人有苦難重壓在身。 他不知道將來的事，其實將來如何，誰能告訴他呢？ 沒有人能掌握生命，將生命留住；也沒有人有權力掌管死期。這場爭戰無人能免；邪惡也不能救那行邪惡的人。 這一切我都見過，我專心考察日光之下所發生的一切事，有時這人管轄那人，令他受害。 \n\n⋯⋯\n\n我專心想要明白智慧，要觀看世上所發生的事。有人晝夜不得闔眼睡覺。 我觀看上帝一切的作為，知道人不能探求日光之下所發生的事；任憑他費多少力探索，都找不出來，智慧人雖說他明白，仍不能找出來。\n\n", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/perspective-images/1770303541272-khv1na.jpeg", "imageAlt": "", "audioUrl": ""}, "JOB": {"book": "約伯記（ 7:17-21）， 13:20-24，（23:3-6）", "theme": "約伯對「信仰為伴侶」的回應⋯⋯。", "description": "人算甚麼，你竟看他為大， 將他放在心上， 每早晨鑒察他， 每時刻考驗他？ 你到何時才轉眼不看我， 任憑我咽下唾沫呢？ 鑒察人的主啊，我若有罪，於你何妨？ 為何以我當你的箭靶， 使我成為你的重擔呢？ 為何不赦免我的過犯， 除掉我的罪孽呢？ 我現今要躺臥在塵土中； 你要切切尋找我，我卻不在了。」\n\n⋯⋯\n\n惟有兩件事不要向我施行， 我就不躲開你的面： 就是把你的手縮回，遠離我身； 又不使你的威嚴恐嚇我。 這樣，你呼叫，我就回答； 或是讓我說話，你回答我。 我的罪孽和我的罪有多少呢？ 求你叫我知道我的過犯與我的罪。 你為何轉臉， 拿我當仇敵呢？ \n\n⋯⋯\n\n惟願我知道哪裏可以尋見上帝， 能到他的臺前， 我就在他面前陳明我的案件， 滿口辯訴。 我必知道他回答我的言語， 明白他向我所要說的。 他豈用大能與我爭辯呢？ 不！他必理會我。 \n\n", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/perspective-images/1770303547174-i7sgw8.jpeg", "imageAlt": "", "audioUrl": ""}}$wib$::jsonb, $wib$信仰，是解釋，是召命，還是同行？

我們信仰上帝，究竟是為了得到答案，
還是為了在無法解釋的人生中，仍然與神同行？或是完成神的召命。

聖經智慧文學裡其實有三個非常誠實、也非常張力十足的聲音，可以幫助我們思考這個問題：
約伯、所羅門，還有傳道者。
 
⸻

一、約伯：信仰不是答案，而是不放手的關係

在《約伯記》裡，約伯經歷極深的苦難。他失去一切，卻最痛苦的不是失去財物，而是感覺神轉臉不看他。

約伯沒有冷靜地問：「這一切為什麼發生？」他反而直接對神說：

「你為何轉臉，拿我當仇敵呢？」「你呼叫，我就回答；或讓我說話，你回答我。」

這不是哲學問題，這是關係裡的質問。

約伯要的不是一套解釋，而是一句回應。不是答案，而是你還在不在？

而神並沒有因為約伯這樣說就責備他。最後約伯說：「我從前風聞有你，現在親眼看見你。」

約伯沒有得到「為什麼受苦」的解釋，卻重新遇見了神。

👉 信仰，在約伯身上，首先是一段不肯放手的關係。

⸻

二、所羅門：智慧與召命，但智慧可能偏離神

接著我們看所羅門。在《列王紀上》3章，神問所羅門：「你願我賜你甚麼？」
所羅門沒有求長壽、財富或勝過仇敵，他承認自己的幼小，求一顆能聽的心，好治理神的百姓。

這件事 大大討神喜悅。神賜給他極大的智慧，也把他沒有求的富足與尊榮一併給他。

但我們都知道故事的後半段。所羅門後來仍然很有智慧、很成功、很有影響力，卻慢慢不再詢問神，容讓偶像，把智慧用來鞏固權力與榮耀。

他的問題不是沒有智慧，而是智慧不再把他帶回神面前。

👉 所羅門提醒我們：智慧若離開敬畏，會從完成召命的工具，變成服務自我的資源。

⸻

三、傳道者：解釋有極限，智慧也有邊界

最後是《傳道書》。傳道者一開始其實非常肯定智慧：「誰如智慧人呢？誰知道事情的解釋呢？」

但他觀察世界之後，卻說了一句非常重的話：「任憑人費多少力探索，都找不出來；智慧人雖說他明白，仍不能找出來。」

他的結論不是「人生毫無意義」，而是：世界不向人完全敞開。

智慧可以幫助我們分辨時機、調整行事，卻不能解釋一切結果，也不能掌控將來。

👉 傳道者為「尋求解釋」劃下了一條清楚的界線。

⸻

四、三個聲音放在一起，我們聽見了什麼？

約伯告訴我們：信仰不是先理解，而是不離開。

所羅門提醒我們：智慧若不回到神面前，會迷失方向。

傳道者則誠實地說：有些事，不會被解釋。

三者合在一起，給了我們一個很重要的提醒：

信仰不是為了給我們所有答案，而是使我們在無法回答的人生裡，仍然與神同行。

⸻

結語

也許在你的信仰旅程中，你曾渴望一個解釋，一個理由，一個「為什麼」。

聖經沒有嘲笑這個渴望，但它溫柔地把我們帶到更深的一步：

👉 不是所有問題都有答案，但所有人生，都可以有同行。

願我們追求的智慧，不是讓自己更自信，而是讓自己更願意留在神面前。

$wib$, $wib$https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1770305230026-j8m5jb.mp3$wib$, $wib$["這六堂課下來，你對「神裏」的智慧得知了多少？", ""]$wib$::jsonb, $wib$智慧是學會在不同人生狀態中，知道該用誠實來活。$wib$, CURRENT_TIMESTAMP);
INSERT INTO "WisdomModule" ("id","cycleId","title","subtitle","sortOrder","status","lifeQuestions","perspectives","tensionGuide","tensionGuideAudioUrl","discussionPrompts","summary","updatedAt") VALUES ($wib$wib-module-9$wib$, $wib$wib-cycle-2$wib$, $wib$第 9 課｜進階課題$wib$, $wib$內容正在規劃中$wib$, 9, $wib$draft$wib$, $wib$[{"id": "2bfd8a65-7bde-44a9-aab2-6ce1336f7482", "text": "思考一個與本階段主題相關的問題。", "type": "open", "options": [], "mediaUrl": "", "imageUrl": "", "imageAlt": ""}]$wib$::jsonb, $wib${"PROVERBS": {"book": "節錄於約翰福音 11章 1-44", "theme": "復活在我，生命在我", "description": "有一個患病的人，名叫拉撒路，住在伯大尼，⋯⋯她姊妹兩個就打發人去見耶穌，說：「主啊，你所愛的人病了。」 耶穌聽見，⋯⋯ 聽見拉撒路病了，就在所居之地仍住了兩天。然後對門徒說：「我們再往猶太去吧。」 門徒說：「拉比，猶太人近來要拿石頭打你，你還往那裏去嗎？」 耶穌回答說：「白日不是有十二小時嗎？人在白日走路，就不致跌倒，因為看見這世上的光。 若在黑夜走路，就必跌倒，因為他沒有光。」 ⋯⋯多馬，又稱為低土馬，就對那同作門徒的說：「我們也去和他同死吧。」\n⋯⋯ 耶穌對她說：「復活在我，生命也在我。信我的人雖然死了，也必復活； 凡活着信我的人必永遠不死。你信這話嗎？」 ⋯⋯\n耶穌哭了\n⋯⋯ 猶太人就說：「你看他愛這人是何等懇切。」 其中有人說：「他既然開了瞎子的眼睛，豈不能叫這人不死嗎？」\n耶穌又心裏悲歎，來到墳墓前；⋯⋯耶穌舉目望天，說：「父啊，我感謝你，因為你已經聽我。 我也知道你常聽我，但我說這話是為周圍站着的眾人，叫他們信是你差了我來。」 說了這話，就大聲呼叫說：「拉撒路出來！」 那死人就出來了，手腳裹着布，臉上包着手巾。耶穌對他們說：「解開，叫他走！」\n\n", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1775180240627-vqv5ve.mp3"}, "ECCLESIASTES": {"book": "節錄於約翰福音 11章 45-", "theme": "殺害耶穌的陰謀", "description": "那些來看馬利亞的猶太人見了耶穌所做的事，就多有信他的； 但其中也有去見法利賽人的，將耶穌所做的事告訴他們。 祭司長和法利賽人聚集公會，說：「這人行好些神蹟，我們怎麼辦呢？ 若這樣由着他，人人都要信他，羅馬人也要來奪我們的地土和我們的百姓。」 內中有一個人，名叫該亞法，本年作大祭司，對他們說：「你們不知道甚麼。 獨不想一個人替百姓死，免得通國滅亡，就是你們的益處。」 他這話不是出於自己，是因他本年作大祭司，所以預言耶穌將要替這一國死； 也不但替這一國死，並要將神四散的子民都聚集歸一。 從那日起，他們就商議要殺耶穌。\n所以，耶穌不再顯然行在猶太人中間，就離開那裏往靠近曠野的地方去，到了一座城，名叫以法蓮，就在那裏和門徒同住。\n猶太人的逾越節近了，有許多人從鄉下上耶路撒冷去，要在節前潔淨自己。 他們就尋找耶穌，站在殿裏彼此說：「你們的意思如何，他不來過節嗎？」 那時，祭司長和法利賽人早已吩咐說，若有人知道耶穌在哪裏，就要報明，好去拿他。", "imageUrl": "", "imageAlt": "", "audioUrl": ""}, "JOB": {"book": "約伯記", "theme": "崩潰", "description": "痛苦沈思。", "imageUrl": "", "imageAlt": "", "audioUrl": ""}}$wib$::jsonb, $wib$這是一個待開發的張力引導主題。$wib$, $wib$$wib$, $wib$["這是一個待開發的討論題目。"]$wib$::jsonb, $wib$待開發的智慧總結。$wib$, CURRENT_TIMESTAMP);
