INSERT INTO "WisdomModule" ("id","cycleId","title","subtitle","sortOrder","status","lifeQuestions","perspectives","tensionGuide","tensionGuideAudioUrl","discussionPrompts","summary","updatedAt") VALUES ($wib$wib-module-12$wib$, $wib$wib-cycle-2$wib$, $wib$第 12 課｜進階課題$wib$, $wib$內容正在規劃中$wib$, 12, $wib$draft$wib$, $wib$[{"id": "d496fa26-103c-4fdb-b333-77b430f094a4", "text": "思考一個與本階段主題相關的問題。", "type": "open", "options": [], "mediaUrl": "", "imageUrl": "", "imageAlt": ""}]$wib$::jsonb, $wib${"PROVERBS": {"book": "箴言", "theme": "秩序", "description": "生活常規。", "imageUrl": "", "imageAlt": "", "audioUrl": ""}, "ECCLESIASTES": {"book": "傳道書", "theme": "虛空", "description": "人生有限。", "imageUrl": "", "imageAlt": "", "audioUrl": ""}, "JOB": {"book": "約伯記", "theme": "崩潰", "description": "痛苦沈思。", "imageUrl": "", "imageAlt": "", "audioUrl": ""}}$wib$::jsonb, $wib$這是一個待開發的張力引導主題。$wib$, $wib$$wib$, $wib$["這是一個待開發的討論題目。"]$wib$::jsonb, $wib$待開發的智慧總結。$wib$, CURRENT_TIMESTAMP);
INSERT INTO "WisdomModule" ("id","cycleId","title","subtitle","sortOrder","status","lifeQuestions","perspectives","tensionGuide","tensionGuideAudioUrl","discussionPrompts","summary","updatedAt") VALUES ($wib$wib-module-13$wib$, $wib$wib-cycle-3$wib$, $wib$第 1 課 苦難的叫喚$wib$, $wib$在最絕望的苦難中，是否沒有什麼可做？$wib$, 1, $wib$published$wib$, $wib$[{"id": "e83137ef-4324-4569-8265-515e27b829ac", "text": "影片中的角色，在苦難和絕望當前，他選擇了做什麼？", "type": "multi_choice", "options": ["後悔", "逃避", "燃續生命"], "mediaUrl": "https://youtube.com/shorts/sOGBUj9pJXM?si=avsRhu-Vbs9B_QPN", "imageUrl": "", "imageAlt": ""}, {"id": "92d6c00d-a8b2-47ff-8693-4c7fd2273a6a", "text": "在苦難和絕望時，人選擇逃避，後悔，燃續生命。可能反映著什麼心態？", "type": "open", "options": [], "mediaUrl": "", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/life-question-images/1770953739410-icpfwi.jpg", "imageAlt": ""}, {"id": "6844807d-98ff-4692-951c-8fe47e0a2e3a", "text": "聖經中我們不難找出當苦難和絕望時候，人發出對神的呼喚，例如在哈巴谷書 1:2-4   「上主啊，我要呼求多久，你才垂聽？你才救我們脫離強暴？ 你為什麼要我看見這樣的災難呢？你怎能容忍這種壞事呢？我的周圍盡是毀壞、強暴，到處都是打鬥、爭吵。 法律沒有力量，沒有作用；正義永遠不得伸張。壞人欺壓義人，正義被歪曲了。 」\n\n你有沒有經驗這種悲哀禱告。", "type": "multi_choice", "options": ["有", "沒有"], "mediaUrl": "", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/life-question-images/1770959290284-kf85me.jpeg", "imageAlt": ""}]$wib$::jsonb, $wib${"PROVERBS": {"book": "約伯記 1:1-3, 6-22", "theme": "智慧文學為什麼用一種戲劇方式去編寫約伯去經驗「神的智慧」的故事", "description": "有一個人名叫 約伯 ，住在 烏斯 地區；他是一個正直的好人，敬畏上帝，不做任何壞事。 他有七個兒子，三個女兒。 他擁有七千隻羊，三千隻駱駝，一千頭牛，五百匹驢。此外，他有成群的僕人；在東方人當中，他算是首富的了。 有一天，天上的神子們 侍立在上主面前，撒但 也在他們當中。 上主問撒但：「你到哪裡去了？」 撒但回答：「我漫游地上，這裡走走，那裡走走。」 上主問：「你注意到我的僕人 約伯 沒有？世上再也沒有像他那樣的人。他是一個正直的好人，敬畏我，不做任何壞事。」 撒但回答：「要不是有利可圖， 約伯 還敬畏你嗎？ 你時常保護他、他的家，和他所有的一切。你賜福給他，使他事事順利；他的牲畜漫山遍野，不可勝數。 現在你若把他所有的都拿走，看他不當面咒罵你！」 上主對撒但說：「好吧，他所有的一切都在你手中，由你擺布，只是不許你加害他本身。」於是撒但從上主面前退出。 有一天， 約伯 的兒女們都在大哥家裡歡宴飲酒， 有報信的跑來報告 約伯 ：「牛正在田裡耕犁，驢在一旁吃草的時候， 示巴 人突然來襲，把牲口都搶走了，殺了你所有的僕人，只有我一個人逃脫，來向你報信。」 他還沒有說完，另一個僕人跑來，說：「雷電從天而降，擊殺了羊群和牧羊人，只有我一個人倖免，來向你報信。」 他還在說話的時候，又有一個僕人上來，說：「 迦勒底 人分三隊襲擊我們，把駱駝全部搶走，又殺了你所有的僕人，只有我一個人逃脫，來向你報信。」 他還沒有說完，另一個僕人跑來，說：「你的兒女們正在大哥家裡歡宴飲酒， 有暴風從曠野那裡颳來，把屋子吹倒，屋裡的人都被壓死，只有我一個人倖免，來向你報信。」 於是 約伯 起來，悲傷地撕裂了自己的衣服，剃掉頭髮，伏在地上敬拜， 說：「我空手出生，也要空手回去；上主賞賜的，上主又收回。上主的名應當受稱頌！」 雖然有這一切遭遇， 約伯 並沒有犯罪，沒有責怪上帝。\n\n\n", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1770823850485-c2ff53.mp3"}, "ECCLESIASTES": {"book": "約伯記 2:1-10", "theme": "智慧文學為什麼用「神」和「撒但」對奕場景去營造約伯受苦的原因", "description": "又有一天，上帝的眾使者 來侍立在耶和華面前，撒但也來在其中。 耶和華問撒但說：「你從哪裏來？」撒但回答說：「我從地上走來走去，在那裏往返。」 耶和華對撒但說：「你曾用心察看我的僕人 約伯 沒有？地上再沒有人像他那樣完全、正直、敬畏上帝、遠離惡事。你雖激起我攻擊他，無故吞滅他，他仍然持守他的純正。」 撒但回答耶和華說：「人以皮代皮，情願捨去一切所有的，來保全性命。 但你若伸手傷他的骨頭和他的肉，他必當面背棄 你。」 耶和華對撒但說：「看哪，他在你手中，只要留下他的性命。」 於是撒但從耶和華面前退出去，擊打 約伯 ，使他從腳掌到頭頂長毒瘡。 約伯 就坐在灰燼中，拿瓦片刮身體。 他的妻子對他說：「你仍然持守你的純正嗎？你背棄上帝，死了吧！」 約伯 卻對她說：「你說話，正如愚頑的婦人。唉！難道我們從上帝手裏得福，不也受禍嗎？」在這一切的事上， 約伯 並沒有以口犯罪。 \n\n\n\n", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1770953968439-hdgz8e.mp3"}, "JOB": {"book": "今日在苦難的人", "theme": "《戰場中苦難的人》 - 約伯記 1-2章現代版本", "description": "他原本住在烏克蘭一個鎮。他不富有，不是喜歡政治，只是一個相信秩序的人。他相信春天會來，孩子會長大，相信祈禱不一定改變世界，但至少能讓世界不那麼黑。\n\n清晨，天還沒亮，第一聲爆炸就像撕裂天空的手。不是審判的號角，只是飛彈。\n\n房子還在，窗戶卻不再完整。電話還能撥通，\n卻一個一個，再也沒人接聽。\n\n到了黃昏，他已經知道了。不是「可能」，\n不是「或許」，而是「都沒了」。\n\n孩子死在去避難所的路上。母親死在醫院斷電之後。朋友消失在佔領區，只剩下最後一條語音訊息，像被神掐斷一半的禱告。\n\n他坐在瓦礫中，身上滿是灰塵與血，卻沒有哭。因為連哭，都像是一種奢侈。\n\n他終於開口，卻不是對人。\n\n「我赤身來到這個世界，如今連名字都快被炸掉。這一切若出於你，我還能說什麼？」\n\n但天沒有回答。\n\n第二天，謠言開始流傳。有人說：\n「是因為這個民族太驕傲。」有人說：\n「是因為你們選錯了路。」還有人說：\n「若你們是義人，神怎會讓你們這樣死？」\n\n他聽見了，卻沒有反駁。他只是更深地低下頭，\n像約伯坐在灰燼中，破瓦望著匆忙包著的傷口。\n\n第三天，他再也忍不住了。 \n\n他不是咒詛神，他只是咒詛那一天。「為什麼我沒有死在母腹中？為什麼我睜開眼，卻看見坦克而不是星空？為什麼光照給受苦的人，生命給心裏愁苦的人？」\n\n「神啊，你若是公義的，請你說一句話。不是解釋歷史，不是計算地緣政治，只要告訴我，我為什麼還活著？」\n\n他停下來。世界仍在轟鳴。神仍然沉默。\n\n但他沒有停止對神說話。\n", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1770823660936-gu6kal.mp3"}}$wib$::jsonb, $wib$【戲劇方式去編寫約伯經驗「神的智慧」的故事】

「神的智慧」不是命題，而是經驗；不是公式，而是遭遇。戲劇形式，如詩歌，能令讀者使用感覺去體會。

一、智慧文學處理的問題，有些問題無法用教科書回答

《約伯記》處理的問題是：
	•	義人為何受苦？
	•	神是否公義？
	•	敬虔是否只是交換？
	•	人是否能理解神的治理？

這些問題如果用論文寫，會變成神學辯證。但智慧文學不是抽象哲學。

當一個人坐在灰燼中時，他還能說什麼？戲劇，讓讀者「坐在灰燼裡」，可以沉浸式領會而不是在旁邊評論。


二、戲劇讓「神的沉默」變得可承受

《約伯記》1–2章是敘事；3–37章是辯論；38章以後神才開口。

如果這只是神學論證，神的沉默會變成邏輯漏洞。

但在戲劇中，對比朋友說話、約伯反駁，沉默（天卻沒有聲音）慢慢產生張力。讓讀者在等待。這種等待，讓人有了些感覺和期望。

讓人領會「神不解釋自己，但仍然臨在。」這種智慧，不是資訊。



【智慧文學用「神」和「撒但」對奕場景去帶出約伯受苦的因由】

為了建立一種「智慧視角」。

一、它把苦難從「報應論」中解放出來

在古代以色列的傳統智慧中（如《箴言》），有一個基本原則：義人蒙福，惡人遭禍。就算在耶穌年代，約翰福音 9:1-2 記載的故事，"耶穌在路上看見一個生下來就失明的人。 他的門徒問他：「老師，這個人生來就失明，是誰的罪造成的？是他自己的罪或是他父母的罪呢？」 "

如果沒有天上的場景，約伯的苦難只能有兩種解釋：	他犯了罪 或 神不公義

這兩個答案都會破壞信仰。但作者加入天庭場景後，我們知道：約伯受苦不是因為罪，也不是神失控，而是涉及一個更深層的問題：人是否可以無條件敬畏神？這個場景切斷了「苦難＝懲罰」的簡單邏輯。


二、它把問題從「行為」轉向「動機」

撒但（在原文中是「控告者」）問的問題不是：約伯「有沒有犯罪」？而是：「約伯敬畏神，豈是無故呢？」（1:9）這句話才是整卷書的核心。

焦點不再是外在行為，而是內在動機：人敬畏神，是因為神值得？還是因為神給好處？這個問題，如果用講道形式寫出來，會變得離地。但透過「神和撒但對奕」場景，它變得具體而尖銳。
 
$wib$, $wib$https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1770861463409-o4jpqy.mp3$wib$, $wib$["思考智慧文學\n\t•\t為什麼《傳道書》用獨白？\n\t•\t為什麼《箴言》用父親的勸勉？\n\t•\t為什麼《約伯記》用戲劇？\n用意何在？這三種文體，其實對應三種人類處境來明白 「神的智慧」，對你而言有沒有幫助？分享你的意見。", "苦難不是理論問題，它是存在問題。如果有弟兄姊妹直接對受苦的人說：「神有更高的計劃，你暫時不明白。」，你會不會覺得是一種「廉價安慰」。\n\n但透過天庭場景，神希望我們能明白：約伯的苦難不是偶然，也不是報應，卻仍然沒有簡單答案。這種張力，你同意不同意是另一種「智慧教育」？分享你的意見。"]$wib$::jsonb, $wib$智慧可以在戲劇激盪人生與沉默神回應中反思和領悟。


現在你最擔心不自覺地的是：自我虛偽信仰生活；用信仰名詞操縱別人；還是缺乏謙遜敬畏神的智慧所帶來缺乏靈內動力？$wib$, CURRENT_TIMESTAMP);
INSERT INTO "WisdomModule" ("id","cycleId","title","subtitle","sortOrder","status","lifeQuestions","perspectives","tensionGuide","tensionGuideAudioUrl","discussionPrompts","summary","updatedAt") VALUES ($wib$wib-module-14$wib$, $wib$wib-cycle-3$wib$, $wib$第 2 課  苦難中的安慰$wib$, $wib$哀慟的心 - 尋找身處痛苦的出路$wib$, 2, $wib$published$wib$, $wib$[{"id": "b27bd866-d9d7-48ff-828c-79370b93fa17", "text": "上次課堂請大家思考一吓智慧文學 ：《傳道書》用獨白 ， 《箴言》用父親的勸勉， 《約伯記》用戲劇。 這三種文體，三種文體會令人好像要至身在不同處境，用不同思緒來明白 「神的智慧」，有這種經歷嗎？嘗試用文字寫下或用語音說出來，AI為你轉化為文字。", "type": "open", "options": [], "mediaUrl": "", "imageUrl": "", "imageAlt": ""}, {"id": "beac2ed0-ce9b-4cbd-9077-d14b1169f2c5", "text": "問問大家在安息禮拜時有沒有「哀慟」過？ 和你分享這首歌。\n\n---\n---\n@gogjj2000 12 years ago 【分享送行之人 -禮儀師之奏鳴曲】留言： 本人從事這個行業也滿多年了 說真的 如果不是以一個 想要幫往生者 讓祂(應該是錯字： 不是「祂」是「他」）們走的時候 很帥很漂亮的走完人生的最後一程 我真的不知道我能不能撐的下去 每天都是要二十四小時待命 有時一通電話來 不管你是剛回家還是累到要掛了 還是得去 因為家屬的一通電話 那就表示 他們信任你 他們需要你 有時會很早出門 要忙到零晨才回到家 有時在想自己的小孩會不會不認我這個爸爸 從事這行 什麼是恐懼 對我們來說 往生者從來不是我們所恐懼的 我們怕的是家屬 因為人在失去最親的人時 可能看什麼都不對 我們也不可能跟他們吵 怕的是他們出手傷害我們 很多人都認為 我們這行賺很多 說真的 不多 50K 這樣會多嗎 天天都要待命 有時要忙到連吃飯睡覺都沒時間 這樣會多嗎 我最高記錄 一星期睡不到二十四小時 累歸累 但是 只要家屬的一聲謝謝 那是比什麼提神飲料來的好 只是 現在的我 跟公司提出長期休假 因為 真的 我把我自己的身體累出病了 心臟出問題 晚上每個人都在睡我就是睡不著 每天只睡不到幾小時 醫生說我 精神太緊繃 休息了半個月了還是這樣 這算是職業傷害嗎 但是這是我自己要的工作 。\n---\n---\n一種相伴「哀慟」人的職業。你是不是一個相伴「哀慟」人的天國子民。", "type": "open", "options": [], "mediaUrl": "https://youtu.be/viZQqCDUjVI?si=7kE50qsBCnMLpv7j", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/life-question-images/1771669870192-jux1ns.webp", "imageAlt": ""}]$wib$::jsonb, $wib${"PROVERBS": {"book": "《約伯記》 2:11-13", "theme": "陪伴一個想死的約伯", "description": "約伯 的三個朋友， 提幔 人 以利法 、 書亞 人 比勒達 、 拿瑪 人 瑣法 ，聽說這一切的災禍臨到他身上，各人就從自己的地方相約同來，為他悲傷，安慰他。 他們遠遠地舉目觀看，認不出他來，就放聲大哭。各人撕裂外袍，向空中撒塵土，落在自己的頭上。 他們同他七天七夜坐在地上，一句話也不對他說，因為他們見到了極大的痛苦。\n\n1. 以利法（אֱלִיפַז /Eliphaz）——提幔人\n\n字源：來自希伯來文，由 אֵל（El，神）和 פַּז（paz，精金）組成意思：「我的神是純金」或「神是力量」\n\n提幔（Teman）：以東地區的一個地方，以智慧著稱（耶 49:7）\n\n\n2. 比勒達（בִּלְדַּד / Bildad）——書亞人\n\n字源：可能來自阿卡德語或閃語，解釋有爭議，有學者認為源自 בַּעַל（主）與 דָּד（所愛的），或意為「主所愛的」\n意思：「巴力所愛」或「爭鬥之子」（另一說法）\n\n書亞（Shuah）：亞伯拉罕與基土拉所生之子（創 25:2），為阿拉伯部族之祖\n\n\n3. 瑣法（צֹפַר / Zophar）——拿瑪人\n\n字源：來自希伯來文動詞 צָפַר（tsaphar），意為「跳躍」或「啁啾（鳥鳴）」\n意思：「跳躍者」或「小鳥」，也有學者解為「冠羽」\n\n拿瑪（Naamah）：有學者認為位於阿拉伯半島或以東地區，確切位置尚未確定\n", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1771671480547-1plsp7.mp3"}, "ECCLESIASTES": {"book": "《耶利米書》20:14–18（《約伯記》 第3章 ）", "theme": "聖經中其他經文有詛咒自己的詩句", "description": "耶和華啊，你欺哄了我， 我也被你欺哄了。 你比我強，並且得勝。 我終日成為笑柄， 人人都戲弄我。 我每逢講話的時候，就哀嘆， 我喊叫：「有暴力和毀滅！」 因為耶和華的話終日成了我的凌辱和譏刺。 \n\n【我若說：「我不再提耶和華， 也不再奉他的名講論」， 我心裏便覺得 似乎有燒著的火悶在我骨中， 我忍受不住，不能自禁。 我聽見許多的毀謗， 四圍都是驚嚇； 連我知己朋友都看著我跌倒： 「告他吧，我們要告他！ 或者他被引誘， 我們就能勝他， 在他身上報仇。」 \n然而，耶和華與我同在， 好像可怕的勇士。 因此，迫害我的都絆跌， 不能得勝； 他們大大蒙羞， 由於行事沒有智慧， 必永遠受那不能忘懷的羞辱。 \n\n考驗義人、察看人肺腑心腸的萬軍之耶和華啊， 求你使我得見你在他們身上報仇， 因我已將我的案件向你稟明了。 你們要向耶和華唱歌！ 要讚美耶和華！ 因他救了窮人的性命 脫離惡人的手。 】\n\n願我出生的那日受詛咒！ 願我母親生我的那天不蒙福！ 報信給我父親說 「你得了兒子」， 使我父親甚歡喜的， 願那人受詛咒。 願那人像耶和華所傾覆而不憐惜的城鎮； 願他早晨聽見哀聲， 中午聽見吶喊； 因他沒有在我未出胎就把我殺了， 以致我母親成為我的墳墓， 她卻一直懷著胎 。 我為何出胎見勞碌愁苦， 在羞愧中度盡我的年日呢？\n", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1771670508536-pnzean.mp3"}, "JOB": {"book": "詩篇 88 篇", "theme": "痛苦沈思", "description": "耶和華－拯救我的上帝啊， 我晝夜在你面前呼求； 願我的禱告達到你面前， 求你側耳聽我的懇求！ 因為我心裏滿了患難， 我的性命臨近陰間； 我與下到地府的人同列， 如同無人幫助的人一樣。 我被丟在死人中， 好像被殺的人躺在墳墓裏， 不再被你記得， 與你的手隔絕了。 你把我放在極深的地府裏， 在黑暗地，在深處。 你的憤怒重壓我身， 你用一切的波浪困住我。（細拉） 你把我所認識的人隔在遠處， 使我為他們所憎惡； 我被拘禁，不能出來。 我的眼睛因困苦而昏花； 耶和華啊，我天天求告你，向你舉手。 你豈要行奇事給死人看嗎？ 陰魂還能起來稱謝你嗎？（細拉） 你的慈愛豈能在墳墓裏被人述說嗎？ 你的信實豈能在冥府 被人傳揚嗎？ 你的奇事豈能在幽暗裏為人所知嗎？ 你的公義豈能在遺忘之地為人所識嗎？ 耶和華啊，至於我，我要呼求你； 每早晨，我的禱告要達到你面前。 耶和華啊，你為何丟棄我？ 為何轉臉不顧我？ 我自幼受苦，幾乎死亡； 你使我驚恐，煩亂不安。 你的烈怒漫過我身， 你用驚嚇把我除滅。 這些如水終日環繞我， 一起圍困我。 你把我的良朋密友隔在遠處， 使我所認識的人都在黑暗裏 。\n", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1771671535430-6pfhkd.mp3"}}$wib$::jsonb, $wib$上次講說聖經但透過天庭場景，神希望我們能明白：約伯的苦難不是偶然，也不是報應，是一種安排，是神和控告者對侍的背景，但我們沒有一個完全和簡單答案。

這種張力，是一種「智慧教育」。苦難不是理論問題，它是存在的。在約伯記中神希望我們明白，無論是受苦的人和看見受苦的人都學習在當時的一種經驗。今天談談「浸沉痛苦中的釋放」和「安慰」

--

以上三段經文，痛苦的人在詩詞中陳述自己生不如死的感受，對神呻吟。當中有朋友在旁，有朋友變敵人，也有朋友被隔離。誰的處境更苦。

那三位朋友沒有對受苦的人說：「神有更高的計劃，你暫時不明白。」，這種「廉價安慰」不是八福中耶穌提及的安慰。馬太福音 5:4 「哀慟的人有福了！因為他們必得安慰。」像應許哀慟的人無論是受苦的人和看見受苦的人有「哀慟」，就有福了！因為得安慰。

什麼是哀慟？約伯記中那三個朋友有「哀慟」嗎？約伯有「哀慟」嗎？

「哀慟」有三種意思：

i. 讓現實觸動自己「內心的柔軟度」
古倫神父強調，哀慟是讓他人的痛苦進入自己心中的能力。他常說，很多人築起心牆，不讓悲傷（包括自己和別人）進來；真正有福的人，是那些心沒有硬化、還能被觸動的人。會深度釋放出同理心與憐憫。
  
ii. 曠野教父的「痛悔之淚」
本篤靈修中，溫柔的心靈刺痛，因意識到自己的有限、罪性、以及與神的距離，而流出的眼淚。這不是自我鞭打，而是內心被神的愛觸碰後的融化。古倫神父認為這種哀慟會帶來深度壓抑的釋放。
 
iii. 心理學層面，哀慟作為「放手的過程」 
古倫神父受榮格影響，認為哀慟是健康的哀悼過程（Trauerprozess）。承認失去、面對痛苦、然後放手。凡壓抑哀慟的人，永遠無法真正康復；能哀慟的人，才能真正前行。

古倫神父指出，基督這句話「哀慟的人有福了！因為他們必得安慰。」奇妙在於：哀慟本身就是得安慰的條件。「只有讓自己的心被觸動、被打開的人，才能接受安慰。封閉的心接受不了安慰。」「必得安慰」（παρακληθήσονται / paraklēthēsontai）是神聖被動式（passivum divinum）。意思是：神自己將來安慰他們。這與聖靈的別名「保惠師」（Paraklet，約14:16）直接相連。這是約伯經歷。
 
$wib$, $wib$https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1771754734722-xmf4zf.mp3$wib$, $wib$["我們勸說弟兄姊妹會不會訴諸流行智慧、神的公義、以及家人蒙福（約伯記第8章）。討論一下點解可能會令人感覺懷疑自身對神沒有信心。\n", "", ""]$wib$::jsonb, $wib$一顆能哀慟的心，是一顆沒有硬化的心，是一顆仍然活著、能愛、能被愛觸動的心，這樣的心才能接受神的安慰。$wib$, CURRENT_TIMESTAMP);
INSERT INTO "WisdomModule" ("id","cycleId","title","subtitle","sortOrder","status","lifeQuestions","perspectives","tensionGuide","tensionGuideAudioUrl","discussionPrompts","summary","updatedAt") VALUES ($wib$wib-module-17$wib$, $wib$wib-cycle-3$wib$, $wib$第 3 課 苦難中的無助$wib$, $wib$無自助、無人助、 無神幫助$wib$, 3, $wib$published$wib$, $wib$[{"id": "bdb3a5f8-a5b0-4abf-822e-0eff0ef8de5c", "text": "在第二次世界大戰時，有6百萬猶太人在集中營無助中死去。如今日很多人在加沙、烏克蘭戰火中生活在無助中。這種哀傷無助的感覺，在約伯記和這首音樂中願你能領略點點⋯⋯", "type": "open", "options": [], "mediaUrl": "https://youtu.be/A3CK21RhynY?si=Xnt77Zf5M1v0PH0f", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/life-question-images/1772298365381-1euft2.jpeg", "imageAlt": ""}, {"id": "0b0bda8d-c3e9-483a-8928-5b14c2f02ac5", "text": "在大病中，大家都經歷過無力感。不能自助，連要杯水，去洗手間都要人幫。我想香港大多數人都在死前會經歷這場景，因為香港醫療目標是主要延長生命，不是太注重生命質素。用醫療器材協助延長生命使人存活，卻令有人會感受到「無助感」？", "type": "open", "options": [], "mediaUrl": "", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/life-question-images/1772298544388-nx9941.jpg", "imageAlt": ""}]$wib$::jsonb, $wib${"ECCLESIASTES": {"book": "傳道書 9:1-12", "theme": "死亡面前的無助", "description": "我將這一切事放在心上，詳細研究這些，就知道義人和智慧人，並他們的作為都在上帝手中；或是愛，或是恨，都在他們面前，但人不能知道。 凡臨到眾人的際遇都一樣：義人和惡人，好人，潔淨的人和不潔淨的人，獻祭的和不獻祭的，都一樣。好人如何，罪人也如何；起誓的如何，怕起誓的也如何。 在日光之下發生的一切事中有一件禍患，就是眾人的際遇都一樣，並且世人的心充滿了惡；活著的時候心裏狂妄，後來就歸死人那裏去了。 與一切活人相連的，那人還有指望，因為活著的狗勝過死了的獅子。 活著的人知道必死；死了的人毫無所知，也不再得賞賜，因為他們的名已被遺忘。 他們的愛，他們的恨，他們的嫉妒，早就消滅了。在日光之下所發生的一切事，他們永不再有份了。你只管歡歡喜喜吃你的飯，心中快樂喝你的酒，因為 ⋯⋯ 在你一生虛空的日子，就是上帝賜你在日光之下虛空的日子，當與你所愛的妻快活度日，因為那是你一生中在日光之下勞碌所得的報償。 凡你手所當做的事，要盡力去做；因為在你所必須去的陰間沒有工作，沒有謀算，沒有知識，也沒有智慧。\n⋯⋯ 人不知道自己的定期。魚被險惡的網圈住，鳥被羅網捉住，禍患的時刻忽然臨到，世人陷在其中也是如此。", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1772300715005-4p1bui.mp3"}, "JOB": {"book": "約伯記 9:29-35", "theme": "在神面前無助", "description": "我必被定罪，\n我何必徒然勞苦呢？\n我若用雪水洗身，\n用鹼潔淨我的手掌，\n你還要把我扔在坑裏，\n我的衣服都憎惡我。\n他不像我是個人，使我可以回答他，\n使我們可以一同受審判。\n我們中間沒有仲裁者，\n可以按手在我們兩造之間。\n願他使他的杖離開我，\n不使他的威嚴恐嚇我，\n我就說話，不懼怕他；\n但對我來說，我卻不是這樣。」\n", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1772300792774-ranif2.mp3"}, "PROVERBS": {"book": "約伯記 9:2-24", "theme": "清醒中的無助", "description": "約伯回答說：\n「我真的知道是這樣，\n但人在上帝前怎能成為義呢？\n人若想要與他爭辯，\n千次中也不能回答一次。\n他心裏有智慧，且大有能力。\n誰向上帝剛硬而得平安呢？\n他把山挪移，山卻不知，\n他在怒氣中，把山翻倒。\n他使地震動，離其本位，\n地的柱子就搖撼。\n他吩咐太陽，太陽就不出來，\n又封住眾星。\n他獨自鋪張諸天，\n步行在海浪之上。\n他造北斗、參星、昴星，\n以及南方的星宿；\n他行大事不可測度，\n行奇事不可勝數。\n看哪，他從我旁邊經過，我看不見；\n他走過，我沒有察覺他。\n看哪，他奪去，誰能阻擋他？\n誰敢對他說：『你做甚麼呢？』\n「上帝必不收回他的怒氣，\n扶助拉哈伯的，屈身在上帝以下。\n既是這樣，我怎敢回答他，\n怎敢在他之前選擇辯詞呢？\n我雖有義，也不能回答，\n我要向那審判我的懇求。\n我若呼求，縱然他應允我，\n我仍不信他會側耳聽我的聲音。\n他用暴風摧折我，\n無故加增我的損傷。\n他不容我喘一口氣，\n倒使我飽受苦惱。\n若論力量，看哪，他真有能力！\n若論審判，『誰能傳我呢？』\n我雖有義，我的口要定我有罪；\n我雖完全，他必證明我為彎曲。\n我雖完全，不顧自己；\n我厭棄我的性命。\n所以我說，都是一樣；\n完全人和惡人，他都滅絕。\n若災禍忽然帶來死亡，\n他必戲笑無辜人的苦難。\n世界交在惡人手中；\n他蒙蔽世界審判官的臉，\n若不是他，那麼是誰呢？", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1772299602332-btaxgu.mp3"}}$wib$::jsonb, $wib$約伯在約伯記 3，6-7，9-10，12-14章中「無助」的層面，文本裡的無助，其實分成五種層面：


1.	存在和不存在的無助（無力生死）
「我為何不出母胎而死？為何不出母腹就氣絕呢？」（3:11）

「你為何使我出母胎呢？甚願我當時氣絕，沒有眼睛看見我。」（10:18）

「他們等死，卻不得死；求死，勝於求隱藏的珍寶。」（3:21）

「遭受患難的人為何有光賜給他呢？心中愁苦的人為何有生命賜給他呢？」（3:20）


⸻
2.	命運性的無助（神話事、人無力） 

「這人的道路遮隱，上帝又四面圍困他。」（3:23）

「因全能者的箭射中了我，我的靈喝盡其毒；上帝的驚嚇擺陣攻擊我。」（6:4）

「他奪去，誰能阻擋他？誰敢對他說：『你做甚麼呢？』」（9:12）


⸻
3.	體力性的無助（氣力耗盡）

「我有甚麼氣力使我等候？我有甚麼結局使我忍耐？」（6:11）

「我的氣力豈是石頭的氣力？我的肉身豈是銅呢？」（6:12）


⸻
4.	法理性的無助（無仲裁者）

「我們中間沒有仲裁者，可以按手在我們兩造之間。」（9:33）

「既是這樣，我怎敢回答他，怎敢在他之前選擇辯詞呢？」（9:14）


⸻
5.	關係性的無助（神沉默、朋友失信）

「我若呼求，縱然他應允我，我仍不信他會側耳聽我的聲音。」（9:16）

「也無人能施行拯救，脫離你的手。」（10:7）


「在我裏面豈不是無助嗎？」（6:13）是約伯整段最核心的「無助」宣告。



約伯記大6:13 的希伯來文『無助』：
הֲלֹא־עֶזְרָתִי בִי
וְתוּשִׁיָּה נִדְּחָה מִמֶּנִּי׃

音譯：halo ʿezrati bi, vetushiyyah niddeḥah mimmennî

直譯：「我的幫助豈不是在我裡面沒有？智慧（或能力）不是從我被趕走了嗎？」


神幫助、支援、援助、救助被造物，包括人類。神對人是「幫顧護惠」的屬性。

在舊約這個用法：例如：「我的幫助從造天地的耶和華而來。」—— 詩篇 121:2

那裡的「幫助」也是 עֵזֶר (ʿezer)，同字根。

在這裡希伯來文是反問句：הֲלֹא (halo) = 「難道不是嗎？」

意思是「我裡面難道還有幫助嗎？」（暗示：沒有了。），而不是單純說「我很無助」。而是約伯表達對神時刻「照顧和看守」屬性的應許的態度。
$wib$, $wib$$wib$, $wib$["馬太福音 9:36 「他看見一大群人，就憐憫他們；因為他們困苦無助，如同羊沒有牧人一樣。」將「神的憐憫」和「困苦無助」拉上關係，你認為對你學習了解苦難中的人的無助感有什麼幫助？", "馬太福音 9:36 「他看見一大群人，就憐憫他們；因為他們困苦無助，如同羊沒有牧人一樣。」有另兩個描述間接和 「了解苦難中的人的無助感」提供了「條件」和「目標」是什麼呢？"]$wib$::jsonb, $wib$苦難中「無助感覺」並不一定是沒有幫助，沒有解釋因由或沒有解決問題方法，可能是來自沒有同行者。馬太福音 26:36-40  
$wib$, CURRENT_TIMESTAMP);
INSERT INTO "WisdomModule" ("id","cycleId","title","subtitle","sortOrder","status","lifeQuestions","perspectives","tensionGuide","tensionGuideAudioUrl","discussionPrompts","summary","updatedAt") VALUES ($wib$wib-module-15$wib$, $wib$wib-cycle-3$wib$, $wib$第 4 課 苦難的同伴：憤怒$wib$, $wib$追逐解釋而又 「不能接受、不能明白」時刻，它就僅僅跟隨$wib$, 4, $wib$published$wib$, $wib$[{"id": "00b0aaaf-2a8e-4cba-a906-776f2a6a1034", "text": "上一課我們討論了苦難中的無助。馬太福音 26:36-40 有記載救主的無助。 \n\n『耶穌和門徒來到一個地方，名叫 客西馬尼 。他對他們說：「你們坐在這裏，我到那邊去禱告。」 於是他帶着 彼得 和 西庇太 的兩個兒子同去。他憂愁起來，極其難過， 就對他們說：「我心裏非常憂傷，幾乎要死；你們留在這裏，和我一同警醒。」 他就稍往前走，俯伏在地，禱告說：「我父啊，如果可能，求你使這杯離開我。然而，不是照我所願的，而是照你所願的。 他回到門徒那裏，見他們睡着了，就對彼得 說：「怎麼樣？你們不能同我警醒一小時嗎？ 』\n\n\n苦難中無助感覺是並不一定是沒有幫助，沒有解釋或沒有解決問題，可能是來自沒有同行者。", "type": "open", "options": [], "mediaUrl": "https://youtu.be/scOKm4Zixm8?si=m98TvQy_Z3aIX7ei", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/life-question-images/1772904230121-jrxdb6.png", "imageAlt": ""}, {"id": "073d63b1-faa8-4601-930b-294492758281", "text": "我們與弟兄姊妹交往時，多數是就一些事情討論，交流一些經驗心得。這種習憤會不會不知不覺令在痛苦中的弟兄姊妹，感覺不被了解。不被了解而產生憤怒。\n\n\n往往憤怒是會和傷痛相連，但不知道是誰帶動誰？\n", "type": "open", "options": [], "mediaUrl": "", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/life-question-images/1772904255896-3yak2x.png", "imageAlt": ""}]$wib$::jsonb, $wib${"PROVERBS": {"book": "約伯記 4:12-21", "theme": "分享經歷 或是 信仰教導", "description": "「有話暗中傳遞給我，耳朵聽其微小的聲音。世人沉睡的時候，\n從夜間異象的雜念中，恐懼戰兢臨到我身，使我百骨戰抖。有靈從我面前經過，我身上的毫毛豎立。那靈停住，我卻不能辨其形狀；有形像在我眼前。我在靜默中聽見有聲音：『必死的人能比　神公義嗎？壯士能比造他的主純潔嗎？ \n\n\n看哪，主不信靠他的僕人，尚且指他的使者為愚昧，何況那些住在泥屋、根基在塵土裏、被蛀蟲所毀壞的人呢？早晚之間，他們就被毀滅，永歸無有，無人理會。他們帳棚的繩索豈不從中拔出來呢？他們死，且是無智慧而死。』」\n", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1771953737728-jz7zhr.mp3"}, "ECCLESIASTES": {"book": "約伯記 6:1-23 ", "theme": "煩躁不安", "description": "約伯回答說：\n\n惟願我的煩惱被秤一秤，我一切的災害放在天平裏，現今都比海沙更重，所以我說話急躁。\n\n因全能者的箭射中了我，我的靈喝盡其毒；上帝的驚嚇擺陣攻擊我。\n\n野驢有草豈會叫喚？牛有飼料豈會吼叫？食物淡而無鹽豈可吃呢？蛋白有甚麼滋味呢？那些可厭的食物，我心不肯挨近。\n\n惟願我得著所求的，上帝賞賜我所切望的，願上帝把我壓碎，\n伸手將我剪除。我因沒有違棄那聖者的言語，就仍以此為安慰，\n在不止息的痛苦中還可歡躍。\n\n我有甚麼氣力使我等候？\n我有甚麼結局使我忍耐？\n我的氣力豈是石頭的氣力？\n我的肉身豈是銅呢？\n\n在我裏面豈不是無助嗎？智慧豈不是從我心中被趕逐嗎？\n\n「灰心的人，他的朋友當以慈愛待他，因為他將離棄敬畏全能者的心。我的弟兄詭詐，好像河道，像溪水流過的河床，因結冰而混濁，有雪藏在其中，暖和的時候就溶化，炎熱時便從原處乾涸。\n\n商隊偏離道路，上到荒涼之地而死亡。提瑪的商隊瞻望，示巴的旅客等候。他們因希望落空就抱愧。他們因希望落空就抱愧，\n來到那裏便蒙羞。\n\n現在你們正是這樣，看見驚嚇的事就懼怕。我豈說：『請你們供給我，從你們的財物中送禮給我』？或說：『請你們拯救我脫離敵人的手，救贖我脫離殘暴人的手』嗎？", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1772906274429-zn7dj7.mp3"}, "JOB": {"book": "約伯記 8:5-13", "theme": "不了解別人屬靈景況", "description": "你若切切尋求　神，向全能者懇求；你若純潔正直，他必定為你興起，使你公義的居所興旺。你起初雖然微小，日後必非常強盛。\n\n「請你詢問上代，思念他們祖先所查究的。我們不過從昨日才有，一無所知，因我們在世的日子好像影子。他們豈不指教你，告訴你，說出發自內心的言語呢？\n\n「蒲草沒有泥豈能生長？\n蘆荻沒有水豈能長大？它還青翠，沒有割下的時候，比百樣的草先枯槁。凡忘記　神的人，路途也是這樣；不虔敬人的指望要滅沒。」", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1772906302059-7999n0.mp3"}}$wib$::jsonb, $wib$經文解讀

【約伯朋友第4章是信仰分享還是教導】
----
 
1. 為什麼這段經文有關異象特別對約伯刺耳
  
以利法說這話「有靈從我面前經過，我身上的毫毛豎立。那靈停住，我卻不能辨其形狀；有形像在我眼前。」，說有一個權威來源，有靈向他顯現。意思是：「這不是我個人的想法，是神給我的啟示。」等於說：「神啟示我，你不可能是無辜的。」

對正在痛苦中的約伯來說，這是一種「披著靈性」的指控。

⸻ 

2. 約伯朋友是在分享還是教導？這也是整卷 約伯記 的核心張力之一

其實兩者都有，但問題在於他們以為自己在做的事
	•	安慰朋友
	•	提供屬靈解釋
	•	勸約伯悔改

但實際上變成
	•	指控受苦者
	•	用神學壓人
	•	假設自己知道神的原因

【約伯朋友在第8章顯示了不了解約伯】
-----

1. 為什麼說約伯朋友不了解約伯的屬靈景況

在約伯記 的敘事開頭，神已經評價約伯：「完全正直，敬畏神，遠離惡事。」神甚至向 撒但 指出約伯的忠心。

但這些事情約伯的朋友完全不知道，人不是全知的，他們解釋會不完全。但人不認同自己「知道」有限，用追逐簡單公式的解釋，例如：善 → 祝福； 惡 → 災禍 。當約伯遭遇巨大苦難時，他們就自然聯想「一定」是哪裡出問題。套用在約伯身上。

---- 
 
2. 朋友像是勸勉約伯，其實勸勉包含一個前提，令他們不能代入約伯處境                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            

比勒達的話可以簡化成三個重點：如果你尋求神 → 神一定恢復你；古人的智慧也這樣說；忘記神的人必定滅亡

看很屬靈，其實暗含一個推論：如果你現在沒有被恢復（苦難沒有舒緩），那代表你還沒有真正悔改或尋求神。約伯的苦難或問題是屬靈問題造成的。試想一下，就算受苦的人得舒緩，就代表他有真正悔改或尋求神嗎？

----- 

【約伯的憤怒】

約伯記第6章經文裡，可以看到約伯情緒不是單一爆發，而是多層次的痛苦與憤怒：對痛苦本身、對神的困惑、以及對朋友的失望。

--- 
1. 對苦難的憤怒
約伯一開始就說：「惟願我的煩惱被秤一秤…比海沙更重，所以我說話急躁。」是在為自己的激烈情緒辯護。

「因全能者的箭射中了我…上帝的驚嚇攻擊我。」是約伯的第一層憤怒：約伯覺得是神在攻擊他。他無法「理解」為什麼神要這樣對他。

---
2. 認為自己的反應（哀號、憤怒）是正常的
幾個比喻如野驢有草不會叫、牛有飼料不會吼、無鹽的食物難以下嚥

意思是： 如果一切正常，人就不會哀號。約伯說自己哀號，是因他的痛苦是真的。合理化憤怒，痛苦燃燒著憤怒，是第二層憤怒
 
---
3. 約伯最明顯對朋友的憤怒：

他尖銳說：「灰心的人，他的朋友當以慈愛待他。」、責備朋友沒有憐憫心如「乾涸的溪流」，或冬天有冰雪的河

商隊遠遠看見以為有水，走到那裡卻發現乾涸，旅人就因沒水死在沙漠裡。意思是你們看起來像朋友，但在我最需要時發現沒有幫助。




保羅在哥林多前書一章，保羅直言：猶太人要神蹟、希利尼人求智慧，但他所傳的卻是「被釘十字架的基督」。

投射在今天：追求智慧，尋求事情的解釋。希望順景，響往僥倖。是人常有心態。當順景時，事情亨通時，人就將一些原因成為事情「合理」的解釋。這「合理」包括「敬畏神」。

福音不是迎合人，而是要拆毀人自我拯救的幻覺：包括『嚮往順景，事情亨通是祝福』和『自以為事情有「合理」解釋』。而是 銳意將人帶回神救恩的作為。


---  
神的作為常常顛覆人對「合理解釋」的期待。

約伯朋友的神學 = 人類尋求「世界是可解釋的道德秩序」，例如簡單公式：善 → 祝福，惡 → 災禍 ，行為決定後果。在今天中國的「人定勝天」，美國的「強權代表合理」。

以利法：人不可能無辜受苦 （事情有解釋，包括受苦）。比勒達：古人的智慧證明神必賞善罰惡 （過去認知是近乎真理）。瑣法：約伯一定罪有應得（大部分現實是合理）。  
 
約伯朋友其實就像保羅說的那種人，想用智慧理解神的作為。神最後在旋風中回答約伯時（約伯38–41章），神沒有解釋苦難原因，而是問：你知道宇宙如何運作嗎？你能管理萬物嗎？意思是：人「沒有能力」完全「理解神」的治理。

但約伯記描繪一個現象，就算最敬愛神的約伯，也會因朋友對話，激發去追求理解而產生憤怒。
 
---- 
神學家馬丁‧路德 Martin Luther (1483–1546) 

1518年，馬丁·路德 在《海德堡辯題》提出十架神學：人不是在成功、能力與理性中認識神，而是在基督十字架的軟弱與苦難中。救恩不是人靠智慧上升，而是神在耶穌基督的十字架 中降臨拯救。 


---
當事奉不似預期、被誤解、被忽略；當家庭、健康或關係顯出限制；當你覺得自己不可明白、不能理解，想不到「自己認可」合情合理的原因時。
 
這時希望「十架神學」能提醒我們：這未必表示神不在，神不完全。相反，神可能正在你痛苦或艱苦的時候，使你更深認識那位「被釘十字架的基督」，並在你軟弱處顯出祂的能力。 $wib$, $wib$https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1773451088380-7x8lps.mp3$wib$, $wib$["在這次思想苦痛可以帶來負面影響：憤怒。你覺得「十架神學」中鼓勵我們不追逐「解釋」苦難，而去體會苦難的人心靈歷程，會不會是勸慰人的一個出路？", "世界有些苦難可以說是人為的。當基督徒在受苦時，他/她是否應該醒察自己，這是「罪的結果」，這樣基督的贖罪的十字架就好像落空，信徒要承受「罪」的結果就帶有「行為稱義」含意。大家分享基督徒應如看侍「罪的結果」和「苦難」？"]$wib$::jsonb, $wib$ 面對「被釘十字架」的痛苦時，基督不是選擇那手執著刀小子的「憤惱」。而選擇了另一個痛苦的同伴，順服。$wib$, CURRENT_TIMESTAMP);
INSERT INTO "WisdomModule" ("id","cycleId","title","subtitle","sortOrder","status","lifeQuestions","perspectives","tensionGuide","tensionGuideAudioUrl","discussionPrompts","summary","updatedAt") VALUES ($wib$wib-module-16$wib$, $wib$wib-cycle-3$wib$, $wib$第 5 課 苦難的同伴：放棄$wib$, $wib$追逐「有限成功、有限喜悅」死局𠄘受失望的附屬品$wib$, 5, $wib$published$wib$, $wib$[{"id": "e7474196-66fa-4dfa-8e47-a4c2f584dee1", "text": "分享一個榮獲多項國際大獎的短片，包括最佳影片、最佳導演、最佳短片和最佳攝影獎的視頻（不是AI製作）。視頻「救贖」是主角自己描繪他體驗痛苦的人生，當面對自身困苦時，透過內心獨白進行的深刻內省。細味著追逐他心靈，帶動主角面對一次又一次失望，令人可能想像沒有出路人生。你體會這情景嗎？", "type": "open", "options": [], "mediaUrl": "https://youtu.be/ka5pGUTK3GY?si=IfOXu3ukdVH8xs_-", "imageUrl": "", "imageAlt": ""}, {"id": "eeed0c05-64a9-4459-83d3-bc63f2fcb9e1", "text": "讓我們在個人苦難的世界中禱告時，也沒有放棄為其他地方在苦難中的人祈求。", "type": "open", "options": [], "mediaUrl": "https://youtu.be/ys_CoFgLERw", "imageUrl": "", "imageAlt": ""}]$wib$::jsonb, $wib${"PROVERBS": {"book": "約伯記 16-17，19章，21章，23-24章，26-27 章。 這 8 章經文進度", "theme": "憤怒 → 受傷與失望 → 尋找希望 → 對世界失望 → 疲憊與放棄式接受", "description": "16:2「你們安慰人，反叫人愁煩。」\n\n16:9「他（神）發怒撕裂我，逼迫我。」\n\n17:1「我的心靈消耗，我的日子滅盡。」\n\n17:11「我的日子已經過去。」\n\n17:15「我的指望在哪裡呢？」\n\n19:6 「是神傾覆我。」\n\n19:13-16「他把我的兄弟隔在遠處，使我認識的人全然與我生疏。我的親戚都離開了我；我的密友都忘記了我。在我家寄居的和我的使女，都當我是陌生人；我在他們眼中被視為外邦人。我呼喚僕人，他卻不回答；我必須親口求他。我口的氣味令我妻子厭惡，我的同胞都憎惡我。連小男孩也藐視我；我起來，他們都嘲笑我。我的知心朋友都憎惡我；我平日所愛的人向我翻臉。」\n\n19:25「我知道我的救贖主活著。」\n\n21:7「惡人為何存活？」\n\n21:9「他們（惡人）的家宅平安。」\n\n21:13「他們（惡人）度日諸事亨通。」\n\n23:3「惟願我能知道在哪裡可以尋見神。」\n\n23:8–9「我往前行，他不在那裡。」\n\n24:12「受傷的人哀號。」\n\n26:2「無力的人，蒙你何等的幫助！」\n\n27:2「神奪去我的理。」\n\n27:5「我至死必不以自己為不正。」\n", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1773647969048-bngjus.wav"}, "ECCLESIASTES": {"book": "約伯記 28-31", "theme": "「仍然尋求神，但內心幾乎耗盡」的矛盾", "description": "以下節錄自 約伯記 28–31章，可以看到約伯在「尋求智慧與公義」與「對處境幾乎放棄」之間的矛盾張力：\n\n「然而，智慧在哪裡可尋？聰明之處在哪裡呢？\n智慧的價值無人能知，在活人之地也無處可尋。\n深淵說：『不在我內；』海說：『不在我中。』\n智慧非用黃金可得，也不能平白銀為它的價值。\n神明白智慧的道路，曉得智慧的所在。\n因他鑒察直到地極，遍觀普天之下。\n他對人說：『看哪，敬畏主就是智慧；\n遠離惡便是聰明。』」（28:12–13, 23–24, 28）\n\n「惟願我仍像往昔的月分，\n像神保守我的日子。\n那時他的燈照在我頭上；\n我藉他的光行過黑暗。\n我若行義人所行的路，\n城門口的少年人見我就回避，\n老年人也起立站著。」（29:2–3, 7–8）\n\n「但如今，比我年少的人戲笑我；\n他們厭惡我，遠遠躲避我，\n不住地吐唾沫在我臉上。\n我的尊榮如風被驅逐，\n我的福祉如雲過去。\n現在我心極其悲傷，\n困苦的日子將我抓住。」（30:1,10,15–16）\n\n「我與眼睛立約，\n怎能戀戀瞻望處女呢？\n我若與虛謊同行，\n腳若追隨詭詐，\n就願神用公道的天平稱我，\n使他知道我的純正。\n我若以黃金為指望，\n對精金說：『你是我的倚靠』；\n我若因財物豐裕、\n因我手多得資財而歡喜；\n這也是審判官當罰的罪孽。\n惟願有一位肯聽我！\n看哪，在這裡有我所簽的供狀，\n願全能者回答我！」（31:1,5–6,24–25,35）\n", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1773477655321-f4matk.mp3"}, "JOB": {"book": "約伯記 33章 8-30", "theme": "神不是沉默", "description": "「其實，你向我耳朵說話，我聽見你言語的聲音：『我（約伯）是純潔無過的，我（約伯）是無辜的，在我（約伯）裏面沒有罪孽。看哪，上帝找機會攻擊我（約伯），以我（約伯）為他的仇敵，把我（約伯）的腳鎖上木枷，察看我（約伯）一切的道路。』\n\n「看哪，你這話無理，我要回答你，因上帝比世人更大。\n你為何與他爭論：『他任何事都不向人解答』？\n\n上帝說一次、兩次，人卻不理會。\n世人在床上沉睡安眠時，在夢中和夜間的異象裏，上帝就開通世人的耳朵，把警告印在他們心上，好叫人轉離自己的行為，叫壯士遠離驕傲，攔阻人不陷入地府，不讓他命喪刀下。\n\n「人在床上被疼痛懲治，骨頭不住地掙扎，以致生命厭棄食物，\n心中厭惡美味。他的肉消瘦，難以看見；先前看不見的骨頭都凸出來。他的性命臨近地府，他的生命挨近滅命者。\n一千天使中，若有一個作傳話的臨到他，指示人所當行的事，上帝就施恩給他，說：『要救贖他免得下入地府，我已經得了贖價。他的肉要比孩童的肉更嫩；他就返老還童。』\n\n他向上帝禱告，上帝就悅納他；他必歡呼朝見上帝的面，因上帝恢復他的義。\n\n他在人前歌唱說：『我犯了罪，顛倒是非，卻沒有受該得的報應。上帝救贖我的性命免入地府，我的生命也必見光。』「看哪，上帝兩次、三次向人行這一切的事，為要從地府救回人的性命，使他被生命之光照耀。」\n\n\n", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1774049447063-jxnar8.mp3"}}$wib$::jsonb, $wib$【放棄 和 接受】

----- 

跟著約伯記 16-17，19章，21章，23-24章，26-27 章。 這 8 章經文進度體會到憤怒 → 受傷與失望 → 尋找希望 → 對世界失望 → 疲憊與放棄式接受

在世，人以「充滿生命、豐盛、長壽的未來」的盼望鼓勵人，是件美事，卻沒有明白「終末論」的替代盼望神學。試圖以今世「盼望」的圖像取代人面對死亡的失望，看來是好的。

人是被造之物，不是永恆，沒有永遠生命，會歸於無有的。除了回歸造物主，創造之先的的「道」，什麼只是暫時價值。

我們信仰卻要在這「見而未現天國盼望」的「終末論」智慧中活著。若不，就只是在追逐「有限復興、有限喜悅、有限盼望」死局中「失敗、苦痛、失望」又再追逐。

這樣追逐是會有一天放棄的。但追逐永恆就不會「放棄」，也不只是「接受」還會「交託」。


神是沉默 -> 是挑戰「終末論」智慧，因祂被理解為不體恤人的苦難，若是這樣永恆回到神家不是樂事。

故約伯記中反駁針對神沉默的感受，


以利戶 在對約伯說話（32–37章都是他發言）。

伯記 33:8–33，中間確實有很多「我、你、他、上帝」交錯，很容易讀到混亂。 

一，8–11節：以利戶在「引用約伯曾說過的話」，不是以利戶自己的觀點：

以利戶轉述：約伯曾說『神把我當仇敵』

⸻

二、12節開始：以利戶開始反駁約伯

12節開始不再是引用，而是以利戶的回應：

「你這話無理，我要回答你」

「你為何與他(神）爭論？」

「你為何與他（神）爭論：『他任何事都不向人解答』？」

以利戶責備約伯：你為什麼抱怨神不向人解釋？ 

⸻

三、14–30節：以利戶在說「神其實有說話」

這一段裡面：經文中的「他」指神
神說一次、兩次，在夢中開通人的耳朵、懲治人、警告人，救贖人的性命	

👉 神不是沉默的，神其實一直在對人說話（透過夢、痛苦、疾病、天使）
👉 受苦不是神不說話，而是人沒有聽見，人聽不入耳
👉 以利戶的觀點不是「痛苦是懲罰」，而是：痛苦是神的拯救方式

19–28節：神透過痛苦拯救人，這是整段最重要的部分。

邏輯是：痛苦 → 警告 → 悔改 → 神施恩 → 人得救

特別重要的一句是：「我已經得了贖價」。這句在《約伯記》裡非常神學性（像一個救贖的宣告）。

⸻

四、最後 31–33節：回到對約伯直接說話？

以利戶對約伯說，經文「約伯啊，你當留心聽我（神）」，「你若有話說，可以回答我（神）」，「我（神）要把智慧教導你」	

「上帝說一次、兩次，人卻不理會。」


$wib$, $wib$https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1774050092873-gt7t8z.wav$wib$, $wib$["這邏輯：痛苦 → 警告 → 悔改 → 神施恩 → 人得救。你同意嗎？在主救贖福音，你的理解有相同或不同嗎？", "以利戶對約伯說，經文「約伯啊，你當留心聽我（神）」，「你若有話說，可以回答我（神）」，「我（神）要把智慧教導你」，好·像神的沉默被視為我們未能聽到神的聲音。你覺得最能令，最適合，你理解神的回應是用什麼方式？\n"]$wib$::jsonb, $wib$ 「於是耶穌對門徒說：「若有人要跟從我，就當捨己，背起自己的十字架來跟從我。 」馬太福音16:24. 讓我們在復活節日子來臨前，深入思考『捨己』和『背起自己的十字架』自身的意義。$wib$, CURRENT_TIMESTAMP);
INSERT INTO "WisdomModule" ("id","cycleId","title","subtitle","sortOrder","status","lifeQuestions","perspectives","tensionGuide","tensionGuideAudioUrl","discussionPrompts","summary","updatedAt") VALUES ($wib$wib-module-18$wib$, $wib$wib-cycle-3$wib$, $wib$第 6 課 活在有限的智慧中$wib$, $wib$又使眾人都明白 「甚麼」是歷代以來隱藏在創造萬物之上帝裏的奧祕， 為要在現今藉著教會使天上執政的、掌權的知道上帝百般的智慧。  以弗所書 3:9-10$wib$, 6, $wib$published$wib$, $wib$[{"id": "28cbc15a-91be-49ff-aa6a-bad5aa627c12", "text": "上一課和大家談到約伯記一個人物，以利戶，聖經沒有抨價這人物是正面或是負面。他提出苦難「管教論」和約伯（或連約伯本身）的三個朋友的 苦難「懲罰論」形成對比。你有沒有分享。", "type": "open", "options": [], "mediaUrl": "https://youtu.be/FeV46fszupY?si=b8evkw3QMXMEYY6n", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/life-question-images/1775121607043-ttrnw8.jpeg", "imageAlt": ""}, {"id": "f340c07b-c62a-40e8-969c-7fbfa524102b", "text": "探索旅行者1號拍攝的標誌性「暗淡藍點」照片背後的故事。\n\n了解這張距離地球60億公里的遙遠照片如何揭示我們星球的脆弱和獨特性。\n\n聆聽卡爾薩根對我們在宇宙中的位置以及這張非凡照片的永恆意義的深刻思考。", "type": "open", "options": [], "mediaUrl": "https://youtu.be/ikqQMHnmR-c?si=8Xj5drEHiJHNDTGI", "imageUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/life-question-images/1774697758958-vcq0wi.jpeg", "imageAlt": ""}]$wib$::jsonb, $wib${"PROVERBS": {"book": "約伯記 38 章 經節", "theme": "耶和華從旋風中回答約伯說", "description": "你可以讓我知道。\n\n「我立大地根基的時候，你在哪裏？你若明白事理，只管說吧！你知道是誰定地的尺度，是誰把準繩拉在其上嗎？地的根基安置在何處？地的角石是誰安放的？\n\n「當海水衝出，如出母胎，誰用門將它關閉呢？是我用雲彩當海的衣服，用幽暗當包裹它的布，為它定界限，又安門和閂，說：『你只可到這裏，不可越過；你狂傲的浪要到此止住。』\n\n「你有生以來，曾命定晨光，曾使黎明知道自己的地位，抓住地的四極，把惡人從其中驅逐出來嗎？地改變如泥上蓋印，萬物出現如衣服一樣。亮光不照惡人，高舉的膀臂也必折斷。」\n\n「你曾進到海之源，或在深淵的隱密處行走嗎？死亡的門曾向你顯露嗎？死蔭的門你曾見過嗎？地的廣大，你能測透嗎？」⋯⋯\n\n「你曾進入雪之庫，或見過雹的倉嗎？雪雹是我為災難的時候，為打仗和戰爭的日子所預備。光亮從何路分開？東風從何路分散遍地？\n\n「雨有父親嗎？露珠是誰生的呢？冰出於誰的胎？天上的霜是誰生的呢？諸水堅硬如石頭，\n深淵之面凝結成冰。\n\n「你能為昴星繫結嗎？你能為參星解帶嗎？你能按時領出星宿嗎？能引導北斗與其眾星嗎？\n你知道天的定律嗎？你能使地歸其權下嗎？生活常規。", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1774709324819-7zn866.wav"}, "ECCLESIASTES": {"book": "約伯記 第 39 章", "theme": "天地的奧祕", "description": "「誰放野驢自由？誰解開快驢的繩索？我使曠野作牠的住處，使鹽地當牠的居所。牠嘲笑城內的喧嚷，不聽趕牲口的喝聲。諸山是牠漫遊的草場，牠尋找各樣青綠之物。\n\n「野牛豈肯服事你？豈肯在你的槽旁過夜？你豈能用套繩將野牛繫於犁溝？牠豈肯隨你耙鬆山谷之地？你豈可因牠力大就倚靠牠？豈可把你的工交給牠做呢？你豈能靠牠把你的穀物運回，又收聚在你的禾場上嗎？\n\n「鴕鳥的翅膀歡然拍動，但豈是鸛的翎毛和羽毛嗎？因牠把蛋留在地上，使蛋在塵土中得溫暖，卻忘記腳會把蛋踹碎，野獸會踐踏它。牠粗暴待雛，似乎不是自己生的；雖徒然勞苦，也不懼怕。因為上帝使牠忘記智慧，也未將悟性分給牠。\n\n⋯⋯\n就嘲笑馬和騎馬的人。「馬的力量是你所賜的嗎？牠頸項上的鬃是你披上的嗎？是你叫牠跳躍像蝗蟲嗎？牠噴氣之威嚴使人驚惶。牠用蹄在谷中挖地，以能力歡躍；牠出去迎擊仇敵。牠嘲笑懼怕，並不驚惶，也不因刀劍退卻。箭袋在牠身上錚錚有聲，\n槍和短槍閃閃發亮。牠震顫激動，將地吞下；一聽角聲就站不住。每逢角聲一響，牠說：『啊哈！』牠從遠處聞到戰爭的氣息，聽見軍官如雷的吼聲和吶喊。\n\n「鷹展開翅膀向南飛翔，豈是藉著你的智慧嗎？大鷹上騰在高處搭窩，\n豈是聽你的指示嗎？牠住在山巖，以山峰和堅固之所為家，從那裏窺察食物，眼睛自遠方瞭望。牠的雛吸血；被殺的人在哪裏，牠也在哪裏。」", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1774714754788-q9k99m.mp3"}, "JOB": {"book": "約伯記 40， 42章", "theme": "約伯的反思", "description": "看哪，我是卑賤的！我用甚麼回答你呢？我只好用手摀住我的口。我說了一次，就不回答；\n說了兩次，不再說了。\n\n我知道，你萬事都能做；你的計劃不能攔阻。誰無知使你的旨意隱藏呢？因此我說的，我不明白；這些事太奇妙，是我不知道的。求你聽我，我要說話；我問你，求你讓我知道。我從前風聞有你，現在親眼看見你。因此我撤回，在塵土和爐灰中懊悔。", "imageUrl": "", "imageAlt": "", "audioUrl": "https://bxyqjzxvloxpyuxijewh.supabase.co/storage/v1/object/public/tts-audio/1774714659315-c3eqeh.wav"}}$wib$::jsonb, $wib$約伯記 38–42 章（神從旋風中說話、約伯回應、最後復興）其實有幾種主要解釋路線，觀點類型 → 代表神學家 → 出處來源 解說。

神學界其實有三種主流理解：

(1) 神顯現，讓約伯重新認識祂，而不是解釋發生什麼事
(2) 神顯示智慧，不給答案
(3) 神解釋世界，不解釋苦難，讓人認識神


1. 文學神學觀點：神的回答是「刻意不解釋苦難」

比較新的學術研究（20世紀後）認為神故意不回答約伯的問題，因為這本書要表達的是 苦難沒有簡單答案，同時約伯是否有了解釋就真得到安慰，而是需要神同在認可。 

核心思想
	•	約伯沒有得到「原因」 
	•	但他得到「神自己」
	•	神的顯現比答案更重要

出處
	•	Wikipedia – Job 42 的學術參考與結構說明 引用多本學術著作（Crenshaw、Wilson、Kugler 等），指出 38–42 章是「神顯現 + 約伯回應」，而不是哲學解釋苦難。 ￼
	•	Reddit 的學術討論中（AcademicBiblical）也提到 Carol Newsom、David Clines


2. 舊約研究學者認為神的話不是「回答問題」，而是證明人根本沒有能力審判神。

核心觀點

神問約伯你在哪裡，當我立地基的時候？意思不是責備，而是指出：
	•	人不能用「道德邏輯」去審判神
	•	神的智慧比報應神學或管教神學更高

出處 
	•	StudyLight – Lange’s Commentary（19世紀學術註釋） 認為38–42 章是整本書「神的最終裁決」，重點是神的威嚴與智慧超越人類理解。 ￼
	•	CSB Study Bible Commentary – Job 簡介 指出以利戶（32–37章）是為 38–42 章鋪路，整本書最後的焦點其實是「神自己」。 ￼


3. 神不是回答「為什麼受苦」，而是重建約伯對神的認識

很多現代神學家認為 38–42 章的重點不是解釋苦難原因，而是讓約伯重新認識神，透過創造的智慧與創造秩序。

核心觀點

神透過自然界的問題（海、星宿、野獸、暴風）告訴約伯：
	•	世界不是混亂的
	•	但也不是人能完全理解的
	•	因此「信任神」比「知道答案」更重要

出處
	•	Working Preacher 對約伯記 38 章的學術講解 指出神的問題不是為了羞辱約伯，而是重新調整他對神與世界的理解。 ￼
	•	The Gospel Coalition – Christopher Ash 約伯記註釋 認為神讓約伯承認自己「說了沒有知識的話」，重點是神的主權與智慧，而不是解釋苦難。 ￼
